/* ══════════════════════════════════════
   POST GRID (cards 3:4 — Large layout keeps 4:5)
   Every card is forced to the SAME 4:5 box, and whatever sits inside
   (image / video / carousel / collection wrapper) is stretched to fill
   it — so no card can ever come out shorter or cut off.
══════════════════════════════════════ */
.grid{
    display:grid;
    grid-template-columns:repeat(3, minmax(0, 1fr));
    grid-auto-rows:auto;
    align-items:stretch;
    gap:2.5px;
    width:100%; max-width:var(--max-w); margin:0 auto;
    padding:2.5px 0 0;
}
.grid .meme-card{
    display:block;
    border-radius:0; background:rgba(255,255,255,0.03); position:relative; overflow:hidden;
    aspect-ratio:3/4;
    width:100%; height:auto; min-height:0; max-height:none; margin:0;
}
.grid .meme-card .media-box{
    position:absolute; inset:0;
    width:100%; height:100%; max-height:none; margin:0; padding:0;
    display:block; overflow:hidden; border-radius:0; cursor:pointer;
}
.grid .meme-card .media-box img,
.grid .meme-card .media-box video{
    position:absolute; inset:0;
    width:100%; height:100%; max-height:none; object-fit:cover; display:block; border-radius:0;
    cursor:pointer;
}
/* direct wrappers inside the media box (carousels / collection slides) also fill the card */
.grid .meme-card .media-box > div:not(.card-badges):not(.card-text-overlay):not(.card-pin-indicator):not(.new-badge){
    position:absolute; inset:0; width:100%; height:100%; max-height:none;
}
.grid .meme-card > img,
.grid .meme-card > video{
    position:absolute; inset:0; width:100%; height:100%; object-fit:cover; display:block; cursor:pointer;
}
.grid .meme-card .top-bar,
.grid .meme-card .caption,
.grid .meme-card .icon-bar{ display:none; }
.grid .meme-card .new-badge{
    position:absolute; top:6px; left:6px; font-size:8px; padding:2px 6px;
    pointer-events:none;
}
.grid .meme-card:hover::after{
    content:''; position:absolute; inset:0; background:rgba(0,0,0,0.15);
    pointer-events:none;   /* overlay never swallows the click */
}

/* ── top-right badges on a grid card (pin icon + media-type icon, side by side) ── */
.grid .meme-card .card-badges{
    position:absolute; top:clamp(6px, 1.4vw, 7px); right:clamp(6px, 1.4vw, 7px); z-index:6;
    display:flex; align-items:center; gap:clamp(5px, 1.2vw, 6px);
    pointer-events:none;
    filter:drop-shadow(0 1px 3px rgba(0,0,0,0.75));
}
.grid .meme-card .card-badges .card-pin-indicator{
    position:static; top:auto; right:auto;
    font-size:14px; color:#ff2d2d; display:flex; align-items:center;
    filter:none;
}
.grid .meme-card .card-badges .dz-type-icon{
    display:flex; align-items:center; justify-content:center;
    width:clamp(19px, 1.5vw + 12px, 21px); height:clamp(19px, 1.5vw + 12px, 21px); color:#fff; line-height:1;
}
.grid .meme-card .card-badges .dz-type-icon svg{
    width:100%; height:100%; display:block; fill:currentColor;
}
/* GIF: small solid badge, like the little labels Instagram uses */
.grid .meme-card .card-badges .dz-type-icon.dz-gif{
    width:auto; height:auto; padding:2px 5px; border-radius:5px;
    background:#fff; color:#111;
    font-size:clamp(8.5px, .2vw + 7.5px, 9px); font-weight:800; letter-spacing:.4px; line-height:1;
}
.grid .meme-card .media-box > .card-pin-indicator{ top:7px; right:28px; }

/* ── text post caption written on the default text image ── */
.grid .meme-card .card-text-overlay{
    position:absolute; inset:0; z-index:2;
    display:flex; align-items:center; justify-content:center;
    padding:clamp(22px, 5vw, 26px) clamp(9px, 2.5vw, 12px) clamp(14px, 3.5vw, 18px);
    background:rgba(0,0,0,0.45);
    pointer-events:none; text-align:center;
}
.grid .meme-card .card-text-overlay span{
    display:-webkit-box;
    -webkit-box-orient:vertical;
    -webkit-line-clamp:8;      /* too long → cut off with "…" */
    overflow:hidden;
    font-size:clamp(.55rem, .4rem + .9vw, .7rem); line-height:1.45; font-weight:500; color:#fff;
    word-break:break-word;
    text-shadow:0 1px 4px rgba(0,0,0,0.6);
}
@media (max-width:490px){ .grid .meme-card .card-text-overlay span{ -webkit-line-clamp:7; } }

/* ── paginated grids (first 9, then next 9 on scroll) ── */
.grid.dz-paged:not(.dz-live) > .meme-card{ display:none; }
.grid.dz-paged > .meme-card.dz-hold{ display:none; }
.grid .meme-card.dz-reveal{ animation:dzCardIn .45s cubic-bezier(.22,1,.36,1) both; }
@keyframes dzCardIn{ from{ opacity:0; transform:translateY(10px); } to{ opacity:1; transform:translateY(0); } }

/* ── grid skeleton cards ── */
.dz-skel-card{
    position:relative; overflow:hidden;
    aspect-ratio:3/4;
    background:rgba(255,255,255,0.05);
}
.dz-skel-card::after{
    content:''; position:absolute; inset:0;
    background:linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent);
    transform:translateX(-100%);
    animation:dzGridShimmer 1.4s ease-in-out infinite;
}
@keyframes dzGridShimmer{ 100%{ transform:translateX(100%); } }
.dz-sentinel{ grid-column:1/-1; height:1px; pointer-events:none; }

/* ══════════════════════════════════════
   FEATURED POST · ARCHIVE · SELECT MODE · BLOCK POPUP · SHARE CARD
══════════════════════════════════════ */
.ft-card{
    display:flex; align-items:center; gap:12px; box-sizing:border-box;
    width:calc(100% - 24px); max-width:calc(var(--max-w) - 24px); margin:12px auto 14px; padding:7px 10px;
    border-radius:5px; background:rgba(255,255,255,0.05); cursor:pointer; -webkit-tap-highlight-color:transparent;
}
.ft-thumb{ flex:0 0 auto; width:44px; aspect-ratio:1/1; border-radius:6px; overflow:hidden; background:rgba(255,255,255,0.06); }
.ft-thumb img, .ft-thumb video{ width:100%; height:100%; object-fit:cover; display:block; }
.ft-body{ flex:1 1 0; min-width:0; }
.ft-tag{ display:flex; align-items:center; gap:4px; font-size:10px; font-weight:700; letter-spacing:.8px; text-transform:uppercase; color:#FF2D2D; }
.ft-note{ margin-top:2px; font-size:13px; font-weight:600; line-height:1.35; color:#fff; display:-webkit-box; -webkit-box-orient:vertical; -webkit-line-clamp:1; overflow:hidden; word-break:break-word; }
.ft-cap{ margin-top:1px; font-size:11.5px; line-height:1.35; color:rgba(255,255,255,.55); display:-webkit-box; -webkit-box-orient:vertical; -webkit-line-clamp:1; overflow:hidden; word-break:break-word; }
.dz-filtering #featuredPost{ display:none; }
@media (max-width:430px){ .ft-thumb{ width:40px; } .ft-note{ font-size:12px; } .ft-cap{ font-size:11px; } }

/* select mode (Memes grid, owner) */
.dz-pick-dot{ display:none; position:absolute; top:8px; left:8px; z-index:8; width:22px; height:22px; border-radius:50%; box-sizing:border-box;
    border:2px solid #fff; background:rgba(0,0,0,.35); align-items:center; justify-content:center; color:#fff; font-size:13px; line-height:1; pointer-events:none; }
body.dz-selecting #memesGrid .dz-pick-dot{ display:flex; }
#memesGrid .meme-card.dz-picked .dz-pick-dot{ background:#FF2D2D; border-color:#FF2D2D; }
#memesGrid .meme-card.dz-picked .dz-pick-dot::after{ content:'✓'; font-weight:700; }
body.dz-selecting #memesGrid .meme-card .card-pin-btn,
body.dz-selecting #memesGrid .meme-card .card-add-col-btn{ pointer-events:none; }
body.dz-selecting #memesGrid .meme-card.dz-picked .media-box{ outline:2px solid #FF2D2D; outline-offset:-2px; }
#bulkBar{
    display:none; position:fixed; left:0; right:0; bottom:0; z-index:2147482000;
    padding:10px 12px calc(10px + env(safe-area-inset-bottom, 0px)); background:#070924; box-shadow:0 -8px 24px rgba(0,0,0,.5);
    align-items:center; gap:8px;
}
body.dz-selecting #bulkBar{ display:flex; }
#bulkBar .bk-count{ flex:1 1 auto; min-width:0; font-size:13px; font-weight:600; color:#fff; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
#bulkBar button{ flex:0 0 auto; display:flex; align-items:center; gap:5px; padding:9px 12px; border:none; border-radius:8px; background:rgba(255,255,255,.08); color:#fff;
    font-size:12.5px; font-weight:600; font-family:inherit; cursor:pointer; -webkit-tap-highlight-color:transparent; }
#bulkBar button:disabled{ opacity:.35; pointer-events:none; }
#bulkBar button.bk-del{ color:#FF2D2D; }
#bulkBar button.bk-x{ background:none; padding:9px 6px; color:rgba(255,255,255,.7); font-size:18px; }
@media (max-width:430px){ #bulkBar button{ padding:9px 9px; font-size:12px; } #bulkBar button span{ display:none; } }

/* Block confirmation popup — centred, same dark card as the other sheets */
#blkModal{ align-items:center !important; justify-content:center !important; }
#blkModal .dzm-sheet{ width:min(76vw, 280px); max-height:none; gap:0; padding:0; border-radius:6px; overflow:hidden; text-align:center; animation:dzmPopIn 0.22s cubic-bezier(0.34,1.56,0.64,1); }
.blk-t{ padding:16px 16px 6px; font-size:15px; font-weight:700; line-height:1.3; color:#fff; word-break:break-word; }
.blk-s{ padding:0 16px 14px; font-size:11.5px; line-height:1.5; color:rgba(255,255,255,.6); }
.blk-row{ display:flex; border-top:1px solid rgba(255,255,255,.1); }
.blk-row button{ flex:1 1 0; padding:10px 8px; background:none; border:none; color:#fff; font-size:13.5px; font-weight:600; font-family:inherit; cursor:pointer; -webkit-tap-highlight-color:transparent; }
.blk-row button + button{ border-left:1px solid rgba(255,255,255,.1); }
.blk-row button:hover{ background:rgba(255,255,255,.05); }
.blk-row .blk-go{ color:#FF2D2D; }
@media (max-width:600px){
    #blkModal .dzm-sheet{ width:min(72vw, 250px); border-radius:5px; }
    .blk-t{ padding:13px 13px 5px; font-size:12.5px; }
    .blk-s{ padding:0 13px 11px; font-size:9.5px; line-height:1.45; }
    .blk-row button{ padding:8px 6px; font-size:11px; }
}

/* Share profile card */
.shc-wrap{ padding:12px 14px 4px; }
.shc-wrap canvas{ display:block; width:100%; max-height:52vh; object-fit:contain; border-radius:12px; background:#06071A; }
.shc-btns{ display:flex; gap:8px; padding:10px 14px 14px; }
#shcModal .shc-btns{ align-items:center; }
#shcModal .shc-btns button{ flex:1 1 0; height:30px; min-height:0; padding:0 6px; margin:0; border:1.5px solid var(--track-red, #FF2D2D); border-radius:7px; background:var(--track-red, #FF2D2D); color:#000; font-size:.8rem; font-weight:700; line-height:1; font-family:inherit; cursor:pointer; display:inline-flex; align-items:center; justify-content:center; gap:5px; white-space:nowrap; transition:background .2s ease, transform .15s ease; }
#shcModal .shc-btns button i{ font-size:14px; line-height:1; color:#000; }
#shcModal .shc-btns button:hover{ background:var(--track-red-hover, #ff1a1a); border-color:var(--track-red-hover, #ff1a1a); }
#shcModal .shc-btns button:active{ transform:scale(.97); }
.ft-input{ width:100%; box-sizing:border-box; margin:6px 0 2px; padding:12px; border-radius:8px; border:1px solid rgba(255,255,255,.14); background:rgba(255,255,255,.05); color:#fff; font-size:14px; font-family:inherit; outline:none; }
.ft-input:focus{ border-color:#FF2D2D; }
.ft-pad{ padding:4px 16px 8px; }
.ft-count{ text-align:right; font-size:10px; color:rgba(255,255,255,.4); }

/* ══════════════════════════════════════
   MEMES GRID LAYOUTS — Default (3 columns, above) · Large · List.
   The owner picks one in the Memes ⌄ sheet; it is saved per user and everybody sees it.
   Only #memesGrid ever gets lay-large / lay-list.
══════════════════════════════════════ */
.lst-body{ display:none; }

/* Large — 2 columns, gaps all round, nothing touches the screen edge, rounded corners */
.grid.lay-large{ grid-template-columns:repeat(2, minmax(0, 1fr)); gap:10px; padding:10px 12px 0; }
.grid.lay-large .meme-card,
.grid.lay-large .dz-skel-card{ border-radius:16px; aspect-ratio:4/5; }
.grid.lay-large .meme-card .media-box{ border-radius:16px; }

/* List — one row per post: rounded thumbnail on the left, caption (max 2 lines, then "…") on the right.
   No likes / reposts are shown. The :not(.dz-hold) / .dz-live parts keep paging + search exactly as before. */
.grid.lay-list{ grid-template-columns:minmax(0, 1fr); gap:14px; padding:12px 14px 0; }
.grid.lay-list.dz-live > .meme-card:not(.dz-hold),
.grid.lay-list.dz-paged > .meme-card.dz-sr-show,
.grid.lay-list.dz-paged > .meme-card.dz-hold.dz-sr-show{ display:flex; align-items:flex-start; gap:12px; }
.grid.lay-list .meme-card{ aspect-ratio:auto; background:none; overflow:visible; border-radius:0; }
.grid.lay-list .meme-card:hover::after{ display:none; }
.grid.lay-list .meme-card .media-box{
    position:relative; inset:auto; flex:0 0 auto;
    width:44%; max-width:180px; height:auto; aspect-ratio:16/10;
    border-radius:12px; background:rgba(255,255,255,0.05);
}
.grid.lay-list .meme-card .card-text-overlay{ display:none; }
.grid.lay-list .meme-card .card-add-col-btn{ width:26px; height:26px; font-size:12px; bottom:6px; right:6px; }
.grid.lay-list .meme-card .lst-body{ display:block; flex:1 1 0; min-width:0; cursor:pointer; padding:1px 0; }
.grid.lay-list .meme-card .lst-cap{
    display:-webkit-box; -webkit-box-orient:vertical; -webkit-line-clamp:2; overflow:hidden;
    font-size:12.5px; line-height:1.35; font-weight:600; color:#fff; word-break:break-word; text-align:left;
}
.grid.lay-list .meme-card .lst-cap:empty::before{ content:'No caption'; font-weight:500; color:rgba(255,255,255,.4); }
.grid.lay-list .meme-card .lst-meta{ margin-top:5px; font-size:10.5px; color:rgba(255,255,255,.5); }
.grid.lay-list .dz-skel-card{ aspect-ratio:auto; height:84px; border-radius:12px; }
@media (max-width:430px){
    .grid.lay-list{ gap:12px; padding:10px 12px 0; }
    .grid.lay-list > .meme-card.dz-sr-show, .grid.lay-list.dz-live > .meme-card:not(.dz-hold){ gap:10px; }
    .grid.lay-list .meme-card .lst-cap{ font-size:11.5px; line-height:1.35; }
    .grid.lay-list .meme-card .lst-meta{ font-size:10px; margin-top:4px; }
}

.rp-empty-state{
    grid-column:1/-1; text-align:center; padding:46px 20px 30px; color:var(--muted);
}
.rp-empty-state i{ font-size:2.3rem; display:block; margin-bottom:10px; color:var(--red); }
.rp-empty-state .t{ color:#fff; font-weight:600; font-size:0.92rem; }

/* ══════════════════════════════════════
   PREMIUM SKELETON — scoped to ONLY the profile header area
══════════════════════════════════════ */
.dz-sk{
    position:relative; overflow:hidden;
    background:rgba(255,255,255,0.06);
    border-radius:6px;
}
.dz-sk::after{
    content:'';
    position:absolute; inset:0;
    background:linear-gradient(90deg, transparent, rgba(255,255,255,0.09), transparent);
    transform:translateX(-100%);
    animation:dzShimmer 1.5s infinite;
}
@keyframes dzShimmer{ 100%{ transform:translateX(100%); } }

.spinner-icon {
    display: inline-flex; align-items: center; justify-content: center;
    gap: 3px; height: 16px; vertical-align: middle;
}
.spinner-icon span {
    display: block; width: 3px; background: currentColor; border-radius: 2px;
    animation: btn-bar 1s ease-in-out infinite;
}
.spinner-icon span:nth-child(1) { animation-delay: 0s; }
.spinner-icon span:nth-child(2) { animation-delay: 0.15s; }
.spinner-icon span:nth-child(3) { animation-delay: 0.3s; }
.spinner-icon span:nth-child(4) { animation-delay: 0.45s; }
@keyframes btn-bar {
    0%,100% { height: 4px; opacity: 0.4; }
    50%      { height: 10px; opacity: 1; }
}

/* ══════════════════════════════════════
   ACCOUNT SWITCHER (userKebab)
══════════════════════════════════════ */
#userKebabOverlay {
    display:none;
    position:fixed;
    inset:0;
    background:rgba(0,0,0,0.6);
    backdrop-filter:blur(2px);
    -webkit-backdrop-filter:blur(2px);
    z-index:999998;
}
#userKebabOverlay.open { display:block; animation:ukbFadeIn 0.2s ease; }
@keyframes ukbFadeIn { from{opacity:0;} to{opacity:1;} }
@keyframes ukbPopIn  { from{opacity:0; transform:translate(-50%,-46%) scale(0.96);} to{opacity:1; transform:translate(-50%,-50%) scale(1);} }
@keyframes ukbSlideUp{ from{transform:translateY(100%);} to{transform:translateY(0);} }

#userKebab {
    display:none;
    position:fixed;
    z-index:999999;
    top:50%;
    left:50%;
    transform:translate(-50%,-50%);
    width:360px;
    max-width:90vw;
}
#userKebab.open { display:block; }
#userKebab.open .ukb-sheet { animation:ukbPopIn 0.22s cubic-bezier(0.34,1.56,0.64,1); }

#userKebab .ukb-sheet {
    background:rgba(12,12,28,0.97);
    backdrop-filter:blur(20px);
    -webkit-backdrop-filter:blur(20px);
    border:none;
    border-radius:22px;
    padding:14px 14px 16px;
    box-shadow:0 16px 40px rgba(0,0,0,0.6);
    max-height:80vh;
    display:flex;
    flex-direction:column;
    gap:12px;
}
#userKebab .ukb-handle {
    display:none;
    justify-content:center;
    padding:2px 0 2px;
    flex-shrink:0;
}
#userKebab .ukb-handle span {
    width:38px; height:4px;
    border-radius:2px;
    background:rgba(255,255,255,0.22);
    display:block;
}
#userKebab .ukb-card {
    background:#070924;
    border:none;
    border-radius:6px;
    overflow:hidden;
    flex-shrink:1;
    min-height:0;
    display:flex;
    flex-direction:column;
}
#userKebab .ukb-scroll { overflow-y:auto; }
#userKebab .ukb-header {
    padding:12px 16px 6px;
    font-size:10px;
    color:rgba(255,255,255,0.35);
    letter-spacing:1px;
    text-transform:uppercase;
    flex-shrink:0;
}
#userKebab .ukb-row-wrap { display:flex; align-items:center; position:relative; }
#userKebab .ukb-row {
    display:flex;
    align-items:center;
    gap:10px;
    padding:10px 14px;
    text-decoration:none;
    color:white;
    transition:background 0.2s;
    flex:1;
    min-width:0;
}
#userKebab .ukb-avatar-wrap { position:relative; flex-shrink:0; }
#userKebab .ukb-avatar {
    width:34px; height:34px;
    border-radius:50%;
    border:1.5px solid #FF2D2D;
    object-fit:cover;
    display:block;
}
#userKebab .ukb-dot {
    position:absolute;
    top:-2px; right:-2px;
    width:9px; height:9px;
    background:#FF2D2D;
    border-radius:50%;
    border:1.5px solid rgba(20,20,30,0.95);
}
#userKebab .ukb-info { flex:1; min-width:0; }
#userKebab .ukb-name {
    font-size:13px; font-weight:600;
    white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#userKebab .ukb-sub { font-size:10px; }
#userKebab .unlink-btn {
    opacity:0;
    transition:opacity 0.2s;
    padding:0 14px 0 4px;
    color:rgba(255,255,255,0.3);
    font-size:16px;
    text-decoration:none;
    flex-shrink:0;
    display:flex;
    align-items:center;
}
#userKebab .ukb-divider { border-top:1px solid rgba(255,255,255,0.08); margin:4px 0; flex-shrink:0; }
#userKebab .ukb-add-row {
    display:flex;
    align-items:center;
    gap:10px;
    padding:10px 14px;
    text-decoration:none;
    color:rgba(255,255,255,0.75);
    transition:background 0.2s;
}
#userKebab .ukb-add-icon {
    width:32px; height:32px;
    border-radius:50%;
    display:flex;
    align-items:center;
    justify-content:center;
    flex-shrink:0;
}
#userKebab .ukb-logout-btn {
    display:flex;
    align-items:center;
    justify-content:center;
    gap:8px;
    width:100%;
    padding:14px;
    text-align:center;
    background:#070924;
    border:none;
    border-radius:6px;
    color:#fff;
    font-size:14px;
    font-weight:600;
    cursor:pointer;
    transition:background 0.2s, border-color 0.2s, color 0.2s;
    font-family:inherit;
    flex-shrink:0;
}
#userKebab .ukb-logout-btn:hover {
    background:#0c0f38;
    color:#FF2D2D;
}

@media (max-width:790px) {
    #userKebab {
        top:auto; bottom:0; left:0; right:0;
        transform:none; width:100%; max-width:100%;
        padding:0; box-sizing:border-box;
    }
    #userKebab.open .ukb-sheet { animation:ukbSlideUp 0.28s cubic-bezier(0.32,0.72,0,1); }
    #userKebab .ukb-handle { display:flex; }
    #userKebab .unlink-btn { opacity:1 !important; }
}
/* boxy (not pill / not very round), #070924, no borders — all screen sizes */
#userKebab .ukb-sheet{ border:none !important; background:#070924 !important; }                 /* the modal card */
#userKebab .ukb-card{ border:none !important; border-radius:6px !important; background:#090b29 !important; }   /* inner area: a slightly lighter shade than the modal */
#userKebab .ukb-logout-btn{ border:none !important; border-radius:6px !important; background:#090b29 !important; }
#userKebab .ukb-logout-btn:hover{ background:#0e1136 !important; }
/* NORMAL view: boxier / sharper, but still slightly rounded */
@media (min-width:791px){
    #userKebab .ukb-sheet{ border-radius:8px !important; }
    #userKebab .ukb-card, #userKebab .ukb-logout-btn{ border-radius:4px !important; }
}
#userKebab .ukb-logout-btn{ color:#FF2D2D !important; font-weight:700 !important; }
#userKebab .ukb-logout-btn i{ color:#FF2D2D; }

/* RESPONSIVE: noticeably smaller linked-accounts sheet */
@media (max-width:790px){
    #userKebab .ukb-sheet{ max-height:60vh; padding:5px 10px calc(env(safe-area-inset-bottom,0px) + 10px); gap:8px; border-radius:0 !important; }
    #userKebab .ukb-handle span{ width:30px; height:3px; }
    #userKebab .ukb-header{ font-size:8.5px; padding:7px 12px 3px; }
    #userKebab .ukb-row{ padding:6px 12px; gap:9px; }
    #userKebab .ukb-avatar{ width:27px; height:27px; }
    #userKebab .ukb-dot{ width:8px; height:8px; }
    #userKebab .ukb-name{ font-size:11.5px; }
    #userKebab .ukb-sub{ font-size:9px; }
    #userKebab .ukb-row > i{ font-size:14px !important; }
    #userKebab .unlink-btn{ font-size:14px; padding:0 12px 0 4px; }
    #userKebab .ukb-add-row{ padding:6px 12px; gap:9px; }
    #userKebab .ukb-add-icon{ width:25px; height:25px; }
    #userKebab .ukb-add-icon i{ font-size:15px !important; }
    #userKebab .ukb-add-row span:first-child{ font-size:11.5px !important; }
    #userKebab .ukb-add-row span:last-child{ font-size:9px !important; }
    #userKebab .ukb-divider{ margin:2px 0; }
    #userKebab .ukb-logout-btn{ padding:10px; font-size:12px; gap:6px; }
}

/* ══════════════════════════════════════════════════════════════
   SHARED "LINKED-ACCOUNTS LOOK" for the Vibe Check, Edit Picture,
   Profile Links and Untrack (Tracking) modals.
   Same overlay, same #070924 sheet, same slightly lighter #090b29
   inner card, same boxy corners, same sizing:
     • normal view     → 360px centred modal (8px corners)
     • responsive view → compact bottom sheet (max 60vh, square top)
══════════════════════════════════════════════════════════════ */
#vibePopup, #epPicModal, #profileLinksOverlay, #mrSheet, #colOptsDd, #colNameModal, #svshOverlay, #pmSheet, #dpModal, #mfSheet, #sfSheet, #ftModal, #blkModal, #shcModal, #bkColSheet{
    display:none; position:fixed; inset:0;
    background:rgba(0,0,0,0.6);
    backdrop-filter:blur(2px); -webkit-backdrop-filter:blur(2px);
    align-items:center; justify-content:center;
    isolation:isolate;
}
#vibePopup{ z-index:2147483647; }
#mrSheet, #colOptsDd, #colNameModal, #svshOverlay, #pmSheet, #dpModal, #mfSheet, #sfSheet, #ftModal, #blkModal, #shcModal, #bkColSheet{ z-index:2147483647; }
#profileLinksOverlay{ z-index:999999999; }
#epPicModal{ z-index:999999; }
#vibePopup.open, #epPicModal.open, #profileLinksOverlay.open, #mrSheet.open, #colOptsDd.open, #colNameModal.open, #svshOverlay.open, #pmSheet.open, #dpModal.open, #mfSheet.open, #sfSheet.open, #ftModal.open, #blkModal.open, #shcModal.open, #bkColSheet.open{ display:flex; animation:ukbFadeIn 0.2s ease; }
@keyframes dzmPopIn{ from{ opacity:0; transform:translateY(10px) scale(0.96); } to{ opacity:1; transform:none; } }

.dzm-sheet{
    position:relative;
    width:360px; max-width:90vw; max-height:80vh;
    background:#070924; border:none; border-radius:8px;
    padding:14px 14px 16px;
    box-shadow:0 16px 40px rgba(0,0,0,0.6);
    display:flex; flex-direction:column; gap:12px;
    animation:dzmPopIn 0.22s cubic-bezier(0.34,1.56,0.64,1);
}
.dzm-handle{ display:none; justify-content:center; padding:2px 0; flex-shrink:0; }
.dzm-handle span{ width:38px; height:4px; border-radius:2px; background:rgba(255,255,255,0.22); display:block; }
.dzm-card{
    background:#090b29; border:none; border-radius:4px;
    overflow:hidden; flex-shrink:1; min-height:0;
    display:flex; flex-direction:column;
}
.dzm-scroll{
    overflow-y:auto; min-height:0;
    scrollbar-width:thin; scrollbar-color:rgba(255,255,255,0.15) transparent;
}
.dzm-scroll::-webkit-scrollbar{ width:4px; }
.dzm-scroll::-webkit-scrollbar-thumb{ background:rgba(255,255,255,0.15); border-radius:999px; }
.dzm-header{
    padding:12px 16px 6px;
    font-size:10px; color:rgba(255,255,255,0.35);
    letter-spacing:1px; text-transform:uppercase; flex-shrink:0;
}
.dzm-sub{
    padding:0 16px 10px;
    font-size:11px; color:rgba(255,255,255,0.5); line-height:1.5;
}
.dzm-close-btn{
    display:flex; align-items:center; justify-content:center; gap:8px;
    width:100%; padding:14px;
    background:#090b29; border:none; border-radius:4px;
    color:rgba(255,255,255,0.85); font-size:14px; font-weight:600;
    cursor:pointer; font-family:inherit; flex-shrink:0;
    transition:background 0.2s, color 0.2s;
}
.dzm-close-btn:hover{ background:#0e1136; color:#FF2D2D; }


/* ══════════════════════════════════════════════════════════════
   PROFILE LINKS MODAL — content of the shared linked-accounts look (.dzm-*)
   Rows are built like the account rows: round icon, name, small url, chevron.
══════════════════════════════════════════════════════════════ */
.pl-item{
    display:flex; align-items:center; gap:10px;
    padding:10px 14px; text-decoration:none; color:#fff;
    transition:background 0.2s;
}
.pl-item:hover{ background:rgba(255,255,255,0.06); }
.pl-icon{
    width:34px; height:34px; border-radius:50%; flex-shrink:0;
    border:1.5px dashed rgba(255,255,255,0.3);
    display:flex; align-items:center; justify-content:center;
}
.pl-icon i{ font-size:17px; color:rgba(255,255,255,0.6); }
.pl-info{ flex:1; min-width:0; }
.pl-item-title{ font-size:13px; font-weight:600; color:#fff; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pl-item-url{ font-size:10px; color:rgba(255,255,255,0.4); margin-top:1px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pl-chevron{ font-size:16px; color:rgba(255,255,255,0.3); flex-shrink:0; }
@media (max-width:790px){
    .pl-item{ padding:6px 12px; gap:9px; }
    .pl-icon{ width:27px; height:27px; }
    .pl-icon i{ font-size:14px; }
    .pl-item-title{ font-size:11.5px; }
    .pl-item-url{ font-size:9px; }
    .pl-chevron{ font-size:14px; }
}

/* ══════════════════════════════════════════════════════════════
   UNTRACK / TRACKING SHEET (#mrSheet) — content inside the shared modal look.
   Structure: #mrSheet › .dzm-sheet › .dzm-card › .dzm-scroll ›
              (.dzm-header, .mr-user-row, .mr-row ×3), then .dzm-close-btn.
   Rows match the account / link rows: round dashed icon, label, small sub text.
══════════════════════════════════════════════════════════════ */
.mr-user-row{ display:flex; align-items:center; gap:10px; padding:10px 14px; }
.mr-user-pic{
    width:34px !important; height:34px !important;
    border-radius:50%; object-fit:cover; flex-shrink:0;
    border:1.5px solid #FF2D2D;
}
.mr-username-text{
    font-size:13px; font-weight:600; color:#fff; text-transform:none;
    letter-spacing:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
    min-width:0;
}

.mr-row{
    display:flex; align-items:center; gap:10px; padding:10px 14px; cursor:pointer;
    border-top:1px solid rgba(255,255,255,.08); transition:background .2s;
    -webkit-tap-highlight-color:transparent;
}
.mr-row:hover{ background:rgba(255,255,255,.06); }
.mr-icon{
    width:34px; height:34px; border-radius:50%; flex-shrink:0;
    border:1.5px dashed rgba(255,255,255,.3);
    display:flex; align-items:center; justify-content:center;
    font-size:17px; color:rgba(255,255,255,.6);
}
.mr-label{ font-size:13px; font-weight:600; color:#fff; }
.mr-label.red{ color:#FF2D2D; }
.mr-sub{ font-size:10px; color:rgba(255,255,255,.4); margin-top:1px; line-height:1.35; }
.mr-state-badge{
    margin-left:auto; flex-shrink:0; font-size:9.5px; font-weight:700;
    padding:3px 8px; border-radius:4px; letter-spacing:.3px;
}
.mr-state-badge.on-mute, .mr-state-badge.on-restrict{ background:rgba(255,45,45,.1); color:#FF2D2D; }

@media (max-width:790px){
    .mr-user-row, .mr-row{ padding:6px 12px; gap:9px; }
    .mr-user-pic, .mr-icon{ width:27px; height:27px; }
    .mr-user-pic{ width:27px !important; height:27px !important; }
    .mr-icon{ font-size:14px; }
    .mr-username-text, .mr-label{ font-size:11.5px; }
    .mr-sub{ font-size:9px; }
}

.mr-toast{
    position:fixed;bottom:90px;left:50%;transform:translateX(-50%) translateY(10px);
    background:rgba(8,8,22,.97);border:1px solid rgba(255,45,45,.25);color:#fff;
    padding:9px 24px;border-radius:50px;font-size:12px;
    font-family:'Poppins',sans-serif;z-index:9999999;pointer-events:none;
    box-shadow:0 8px 24px rgba(0,0,0,.6);white-space:nowrap;
    opacity:0;transition:opacity .22s ease,transform .22s ease;
}
.mr-toast.show{opacity:1;transform:translateX(-50%) translateY(0);}

/* RESPONSIVE: the same compact bottom sheet as the linked-accounts modal */
@media (max-width:790px){
    #vibePopup, #epPicModal, #profileLinksOverlay, #mrSheet, #colOptsDd, #colNameModal, #svshOverlay, #pmSheet, #dpModal, #mfSheet, #sfSheet, #ftModal, #blkModal, #shcModal, #bkColSheet{ align-items:flex-end; }
    .dzm-sheet{
        width:100%; max-width:100%; max-height:60vh;
        border-radius:0;
        padding:5px 10px calc(env(safe-area-inset-bottom,0px) + 10px);
        gap:8px;
        animation:ukbSlideUp 0.28s cubic-bezier(0.32,0.72,0,1);
    }
    .dzm-handle{ display:flex; }
    .dzm-handle span{ width:30px; height:3px; }
    .dzm-card{ border-radius:6px; }
    .dzm-header{ font-size:8.5px; padding:7px 12px 3px; }
    .dzm-sub{ font-size:10px; padding:0 12px 8px; }
    .dzm-close-btn{ padding:10px; font-size:12px; gap:6px; border-radius:6px; }
}

/* ══════════════════════════════════════════════════════════════
   COLLECTION + POST MODALS — all built on the shared .dzm-* look
   (same sheet / card / header / close button as Vibe Check, Accounts, Links, Untrack)
   Collection options #colOptsDd · New / Rename #colNameModal · Save-to-Collection #svshOverlay
   Post options #pmSheet · Delete post #dpModal
   Overlay / open / bottom-sheet rules for these ids live in the shared lists above.
══════════════════════════════════════════════════════════════ */

/* ── option rows (Collection options, Post options) ── */
.dzm-item{
    display:flex; align-items:center; gap:10px; padding:10px 14px; cursor:pointer;
    border-top:1px solid rgba(255,255,255,.08); transition:background .2s;
    -webkit-tap-highlight-color:transparent;
}
.dzm-header + .dzm-item{ border-top:none; }
.dzm-item:hover{ background:rgba(255,255,255,.06); }
.dzm-item-ic{
    width:34px; height:34px; border-radius:50%; flex-shrink:0;
    border:1.5px dashed rgba(255,255,255,.3);
    display:flex; align-items:center; justify-content:center;
    font-size:17px; color:rgba(255,255,255,.6);
}
.dzm-item-tx{ flex:1; min-width:0; }
.dzm-item-t{ font-size:13px; font-weight:600; color:#fff; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.dzm-item-s{ font-size:10px; color:rgba(255,255,255,.4); margin-top:1px; line-height:1.35; }
.dzm-item.danger .dzm-item-t{ color:#FF2D2D; }
.dzm-item.danger .dzm-item-ic{ color:#FF2D2D; border-color:rgba(255,45,45,.45); }
#colOptsTitle{ white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }

/* ── form pieces (New / Rename collection, Save sheet "create" screen, Delete post) ── */
.cm-field{ padding:4px 14px 10px; }
.cm-input{
    width:100%; background:rgba(255,255,255,.06); border:none; border-radius:4px;
    padding:10px 12px; color:#fff; font-size:13px; font-family:Poppins,sans-serif;
    outline:none; box-sizing:border-box; transition:background .2s;
}
.cm-input:focus{ background:rgba(255,255,255,.1); }
.cm-input::placeholder{ color:rgba(255,255,255,.25); }

.cm-row{
    display:flex; align-items:center; justify-content:space-between; gap:12px;
    padding:10px 14px; border-top:1px solid rgba(255,255,255,.08);
}
.cm-row-flush{ padding-left:0; padding-right:0; border-top:none; }
.cm-row-tx{ min-width:0; }
.cm-row-t{ font-size:12.5px; font-weight:600; color:#fff; }
.cm-row-s{ font-size:10.5px; color:rgba(255,255,255,.45); margin-top:2px; line-height:1.4; }

.cm-actions{ padding:6px 14px 14px; }
.cm-save{
    display:flex; align-items:center; justify-content:center; width:100%;
    height:var(--rp-action-h); padding:0 14px; border:none; border-radius:var(--rp-action-radius);
    background:var(--track-red); color:#000; font-size:.72rem; font-weight:700; font-family:inherit; line-height:1;
    transition:background .2s, transform .15s;
}
.cm-save:hover{ background:var(--track-red-hover); }
.cm-save:active{ transform:scale(.98); }
.cm-save:disabled{ opacity:.5; pointer-events:none; }
.cm-save.cm-danger{ background:#FF2D2D; color:#fff; }
.cm-save.cm-danger:hover{ background:#ff1a1a; }

/* on/off switch — same look as the Vibe Check switch */
.col-vis-toggle{ position:relative; width:44px; height:25px; flex-shrink:0; display:block; }
.col-vis-toggle input{ opacity:0; width:0; height:0; position:absolute; }
.col-vis-slider{
    position:absolute; inset:0; border-radius:99px; background:rgba(255,255,255,.18);
    cursor:pointer; transition:background .22s ease;
}
.col-vis-slider::before{
    content:''; position:absolute; top:3px; left:3px; width:19px; height:19px; border-radius:50%;
    background:#fff; transition:transform .22s ease;
}
.col-vis-toggle input:checked + .col-vis-slider{ background:var(--red); }
.col-vis-toggle input:checked + .col-vis-slider::before{ transform:translateX(19px); }

/* ── Delete post warning ── */
.dp-warn{ text-align:center; padding:8px 18px 14px; }
.dp-warn-ic{
    width:44px; height:44px; margin:4px auto 10px; border-radius:50%;
    background:rgba(255,45,45,.12); color:#FF2D2D;
    display:flex; align-items:center; justify-content:center; font-size:24px;
}
.dp-warn-t{ font-size:14px; font-weight:700; color:#fff; }
.dp-warn-s{ font-size:11px; color:rgba(255,255,255,.5); line-height:1.6; margin-top:6px; }

/* ── Save-to-Collection sheet (the original look): rounded dark sheet, two screens that slide (list ⇄ create) ── */
#svshOverlay{ backdrop-filter:blur(4px); -webkit-backdrop-filter:blur(4px); }
#svshPanel{
    position:relative; width:100%; max-width:340px;
    background:rgba(12,12,28,0.98);
    backdrop-filter:blur(20px); -webkit-backdrop-filter:blur(20px);
    border:1px solid rgba(255,255,255,0.08);
    border-radius:18px; overflow:hidden; max-height:70vh;
    display:flex; flex-direction:column;
    box-shadow:0 -10px 40px rgba(0,0,0,0.5);
    font-family:Poppins,sans-serif; white-space:normal;
}
@media (max-width:790px){
    #svshPanel{ max-width:100%; border-bottom:none; border-left:none; border-right:none; border-radius:20px 20px 0 0; max-height:82vh; animation:ukbSlideUp .28s cubic-bezier(.32,.72,0,1); }
}
.svsh-switch-slider{ -webkit-tap-highlight-color:transparent; }
.svsh-screens{
    display:flex;width:200%;
    transition:transform .3s cubic-bezier(.32,.72,0,1);
}
.svsh-panel.svsh-create-mode .svsh-screens{ transform:translateX(-50%); }

.svsh-screen{
    width:50%;
    flex-shrink:0;
    padding:8px 0 max(10px, env(safe-area-inset-bottom));
    max-height:82vh;
    overflow-y:auto;
    box-sizing:border-box;
    -webkit-overflow-scrolling:touch;
}
.svsh-screen::-webkit-scrollbar{width:4px;}
.svsh-screen::-webkit-scrollbar-thumb{background:rgba(255,255,255,0.15);border-radius:999px;}

.svsh-handle{
    width:34px;height:3.5px;border-radius:999px;
    background:rgba(255,255,255,0.2);
    margin:0 auto 4px;flex-shrink:0;
}

.svsh-section-label{
    font-size:13px;font-weight:700;color:#fff;
    padding:12px 18px 6px;
}

/* ── ROW ITEMS — matched to idx-sheet-item ── */
.svsh-row{
    display:flex;align-items:center;gap:11px;
    padding:9px 18px;
    color:#fff;text-decoration:none;
    font-size:13px;font-weight:500;
    font-family:Poppins,sans-serif;
    cursor:pointer;
    -webkit-tap-highlight-color:transparent;
    transition:background 0.15s ease;
    border-bottom:1px solid rgba(255,255,255,0.06);
}
.svsh-row:active{background:rgba(255,255,255,0.06);}
.svsh-row-icon{
    font-size:15.5px;color:#f24455;width:18px;text-align:center;flex-shrink:0;
}

.svsh-row-text{ flex:1; min-width:0; }
.svsh-row-title{
    font-size:13px;font-weight:600;color:#fff;
    white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
.svsh-row-sub{
    font-size:11px;color:rgba(255,255,255,0.45);
    margin-top:2px;display:flex;align-items:center;gap:4px;
}

.svsh-chevron{ font-size:18px; color:rgba(255,255,255,0.25); flex-shrink:0; }

.svsh-collections-list{ margin-top:0; }
.svsh-col-thumb{
    width:34px;height:34px;flex-shrink:0;border-radius:9px;
    object-fit:cover;background:rgba(255,255,255,0.08);
}
.svsh-col-thumb-empty{
    display:flex;align-items:center;justify-content:center;
    color:#f24455;font-size:16px;
}

.svsh-add-btn{
    width:26px;height:26px;flex-shrink:0;border-radius:50%;
    border:1.5px solid rgba(255,255,255,0.22);
    display:flex;align-items:center;justify-content:center;
    color:#fff;font-size:15px;
    transition:all .15s ease;
    -webkit-tap-highlight-color:transparent;
}
.svsh-add-btn.svsh-added{
    background:#f24455;border-color:#f24455;
}

.svsh-loading{
    text-align:center;padding:24px;color:rgba(255,255,255,0.35);font-size:13px;
}

/* ── CREATE SCREEN ── */
.svsh-create-topbar{
    display:flex;align-items:center;justify-content:space-between;
    padding:6px 18px 14px;
    border-bottom:1px solid rgba(255,255,255,0.06);
}
.svsh-back-btn{
    width:30px;height:30px;border-radius:50%;
    background:rgba(255,255,255,0.06);border:none;color:#fff;
    display:flex;align-items:center;justify-content:center;
    font-size:19px;cursor:pointer;-webkit-tap-highlight-color:transparent;
    transition:background .18s;
}
.svsh-back-btn:hover{background:rgba(255,45,45,0.18);color:#ff6060;}
.svsh-create-title{ font-size:13.5px;font-weight:700;color:#fff; }
.svsh-done-btn{
    background:none;border:none;color:#f24455;
    font-size:13px;font-weight:700;cursor:pointer;padding:6px 2px;
    font-family:Poppins,sans-serif;-webkit-tap-highlight-color:transparent;
}
.svsh-done-btn:disabled{ opacity:.4; }

.svsh-create-body{ padding:16px 18px 10px; }
.svsh-name-input{
    width:100%;padding:13px 15px;
    background:rgba(255,255,255,0.045);
    border:1px solid rgba(255,255,255,0.09);
    border-radius:13px;color:#fff;font-size:13.5px;
    font-family:Poppins,sans-serif;outline:none;box-sizing:border-box;
    transition:border-color .2s, background .2s;
}
.svsh-name-input::placeholder{ color:rgba(255,255,255,0.22); }
.svsh-name-input:focus{
    border-color:rgba(255,45,45,0.4);
    background:rgba(255,45,45,0.04);
}

.svsh-required-hint{
    font-size:10.5px;color:rgba(255,255,255,0.25);
    margin:7px 2px 20px;
}
.svsh-required-hint.svsh-error{ color:#ff6060; }

.svsh-toggle-row{
    display:flex;align-items:center;justify-content:space-between;
    gap:14px;padding:6px 2px;
}
.svsh-toggle-title{ font-size:13px;font-weight:600;color:#fff; }
.svsh-toggle-sub{ font-size:10.5px;color:rgba(255,255,255,0.35);margin-top:2px; }

.svsh-switch{ position:relative;width:44px;height:26px;flex-shrink:0; }
.svsh-switch input{ opacity:0;width:0;height:0; }
.svsh-switch-slider{
    position:absolute;inset:0;background:rgba(255,255,255,0.15);
    border-radius:999px;cursor:pointer;transition:.2s;
}
.svsh-switch-slider::before{
    content:'';position:absolute;width:20px;height:20px;left:3px;top:3px;
    background:#fff;border-radius:50%;transition:.2s;
}
.svsh-switch input:checked + .svsh-switch-slider{ background:#f24455; }
.svsh-switch input:checked + .svsh-switch-slider::before{ transform:translateX(18px); }

/* Desktop: centered modal */
@media (min-width:791px){
    #svshPanel{ border-radius:18px; max-width:340px; max-height:70vh; animation:dzmPopIn .22s cubic-bezier(.34,1.56,.64,1); }
    .svsh-handle{display:none;}
}

/* 790px — TABLET */
@media (max-width:790px){
    #svshPanel{
        border-radius:18px 18px 0 0;
        max-height:78vh;
    }
    .svsh-screen{ padding:7px 0 max(9px, env(safe-area-inset-bottom)); }
    .svsh-handle{ width:32px;height:3.5px;margin:0 auto 4px; }
    .svsh-section-label{ padding:11px 16px 5px; font-size:12.5px; }
    .svsh-row{ padding:8px 16px; font-size:12.5px; gap:10px; }
    .svsh-row-icon{ font-size:15px; width:17px; }
    .svsh-col-thumb{ width:32px;height:32px;border-radius:8px; }
    .svsh-add-btn{ width:25px;height:25px;font-size:14px; }
    .svsh-create-topbar{ padding:5px 16px 12px; }
    .svsh-create-body{ padding:14px 16px 9px; }
}

/* 490px — LARGE MOBILE */
@media (max-width:490px){
    #svshPanel{
        border-radius:16px 16px 0 0;
        max-height:76vh;
        backdrop-filter:blur(16px);
        -webkit-backdrop-filter:blur(16px);
    }
    .svsh-screen{ padding:6px 0 max(8px, env(safe-area-inset-bottom)); }
    .svsh-handle{ width:30px;height:3px;margin:0 auto 3px; }
    .svsh-section-label{ padding:10px 14px 5px; font-size:12px; }
    .svsh-row{ padding:7px 14px; font-size:12px; gap:9px; }
    .svsh-row-icon{ font-size:14px; width:16px; }
    .svsh-col-thumb{ width:30px;height:30px;border-radius:8px; }
    .svsh-add-btn{ width:24px;height:24px;font-size:13px; }
    .svsh-create-topbar{ padding:5px 14px 11px; }
    .svsh-back-btn{ width:27px;height:27px;font-size:17px; }
    .svsh-create-title{ font-size:13px; }
    .svsh-create-body{ padding:13px 14px 8px; }
    .svsh-name-input{ font-size:13px;padding:12px 14px;border-radius:12px; }
}

/* 390px — STANDARD MOBILE */
@media (max-width:390px){
    #svshPanel{
        border-radius:14px 14px 0 0;
        max-height:74vh;
        backdrop-filter:blur(14px);
        -webkit-backdrop-filter:blur(14px);
        box-shadow:0 -8px 30px rgba(0,0,0,0.45);
    }
    .svsh-screen{ padding:6px 0 max(7px, env(safe-area-inset-bottom)); }
    .svsh-handle{ width:28px;height:3px;margin:0 auto 3px; }
    .svsh-section-label{ padding:9px 12px 4px; font-size:11.5px; }
    .svsh-row{ padding:6.5px 12px; font-size:11.5px; gap:8px; }
    .svsh-row-icon{ font-size:13.5px; width:15px; }
    .svsh-col-thumb{ width:28px;height:28px;border-radius:7px; }
    .svsh-add-btn{ width:22px;height:22px;font-size:12px; }
    .svsh-create-topbar{ padding:4px 12px 10px; }
    .svsh-back-btn{ width:25px;height:25px;font-size:16px; }
    .svsh-create-title{ font-size:12.5px; }
    .svsh-create-body{ padding:12px 12px 7px; }
    .svsh-name-input{ font-size:12.5px;padding:11px 13px;border-radius:11px; }
}

/* 330px — SMALL / COMPACT MOBILE */
@media (max-width:330px){
    #svshPanel{
        border-radius:12px 12px 0 0;
        max-height:72vh;
        backdrop-filter:blur(12px);
        -webkit-backdrop-filter:blur(12px);
        box-shadow:0 -6px 24px rgba(0,0,0,0.4);
    }
    .svsh-screen{ padding:5px 0 max(6px, env(safe-area-inset-bottom)); }
    .svsh-handle{ width:24px;height:2.5px;margin:0 auto 3px; }
    .svsh-screen::-webkit-scrollbar{width:3px;}
    .svsh-section-label{ padding:8px 10px 4px; font-size:11px; }
    .svsh-row{ padding:5.5px 10px; font-size:10.5px; gap:7px; }
    .svsh-row-icon{ font-size:12.5px; width:13px; }
    .svsh-col-thumb{ width:26px;height:26px;border-radius:6px; }
    .svsh-add-btn{ width:20px;height:20px;font-size:11px; }
    .svsh-create-topbar{ padding:4px 10px 8px; }
    .svsh-back-btn{ width:23px;height:23px;font-size:14px; }
    .svsh-create-title{ font-size:11.5px; }
    .svsh-create-body{ padding:10px 10px 6px; }
    .svsh-name-input{ font-size:11.5px;padding:10px 12px;border-radius:10px; }
}

/* ── responsive: same compact sizes as the Accounts / Links / Untrack sheets ── */
@media (max-width:790px){
    .dzm-item{ padding:6px 12px; gap:9px; }
    .dzm-item-ic{ width:27px; height:27px; font-size:14px; }
    .dzm-item-t{ font-size:11.5px; }
    .dzm-item-s{ font-size:9px; }
    .cm-field{ padding:2px 12px 8px; }
    .cm-input{ font-size:11.5px; padding:8px 11px; }
    .cm-row{ padding:8px 12px; }
    .cm-row-t{ font-size:11.5px; }
    .cm-row-s{ font-size:9.5px; }
    .cm-actions{ padding:4px 12px 12px; }
    .col-vis-toggle{ width:40px; height:23px; }
    .col-vis-slider::before{ width:17px; height:17px; }
    .col-vis-toggle input:checked + .col-vis-slider::before{ transform:translateX(17px); }
    .dp-warn{ padding:6px 14px 12px; }
    .dp-warn-ic{ width:38px; height:38px; font-size:21px; }
    .dp-warn-t{ font-size:12.5px; }
    .dp-warn-s{ font-size:10px; }
}

/* ══════════════════════════════════════
   PROFILE PIC MODAL (Vibe Check / Share / Copy Link / QR / Track)
══════════════════════════════════════ */
.modal {
    display: none;
    position: fixed;
    z-index: 2147483647;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0,0,0,0.985);
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 32px;
}
.modal[style*="flex"] {
    display: flex !important;
    align-items: center;
    justify-content: center;
}
.modal-content {
    display: block !important;
    border-radius: 50%;
    object-fit: cover;
    transition: transform 0.3s ease;
    width: min(60vw, 60vh) !important;
    height: min(60vw, 60vh) !important;
    max-width: 700px !important;
    max-height: 700px !important;
    margin: 0 !important;
    padding: 0 !important;
}
@media (max-width:768px){ .modal-content{ max-width:300px !important; max-height:300px !important; } }
.modal-actions{
    display:flex; align-items:center; justify-content:center; gap:clamp(10px, 4vw, 20px);
}

/* Track button inside the pic modal — identical to the solid red Track button. */
.modal-track-btn{
    display:inline-flex; align-items:center; justify-content:center;
    padding:5px clamp(60px, 12.5vw, 80px); min-width:clamp(250px, 52vw, 320px); border-radius:7px;
    font-size:clamp(.84rem, .72rem + .5vw, .92rem); font-weight:700;
    border:1.5px solid var(--track-red); color:#000; background:var(--track-red);
    text-decoration:none; white-space:nowrap;
    margin-top:clamp(14px, 2.9vw, 18px);
    transition:background .2s ease, transform .15s ease;
}
.modal-track-btn:hover{ background:var(--track-red-hover); border-color:var(--track-red-hover); }
.modal-track-btn:active{ transform:scale(0.97); }
.modal-track-btn.pending{
    border-color:rgba(255,255,255,0.15); color:rgba(255,255,255,0.45); background:rgba(255,255,255,0.1);
    font-weight:600;
    cursor:pointer;
}
.modal-track-btn.pending:hover{ background:rgba(255,255,255,0.16); border-color:rgba(255,255,255,0.15); }
.modal-action-btn{
    display:flex; flex-direction:column; align-items:center; gap:8px;
    text-decoration:none; cursor:pointer;
}
.modal-action-icon{
    width:clamp(42px, 6.7vw + 18px, 56px); height:clamp(42px, 6.7vw + 18px, 56px); border-radius:50%;
    background:rgba(30,30,30,0.95);
    display:flex; align-items:center; justify-content:center;
    transition:background 0.2s, transform 0.2s;
}
.modal-action-icon svg{ width:clamp(18px, 1.5vw + 12px, 22px); height:clamp(18px, 1.5vw + 12px, 22px); stroke:var(--red); }
.modal-action-btn span{
    font-size:clamp(10px, .4vw + 8.5px, 11px); color:rgba(255,255,255,0.85); font-weight:500;
    white-space:nowrap; letter-spacing:0.2px;
}
.modal-action-btn:hover .modal-action-icon{ background:rgba(50,50,50,0.95); transform:translateY(-2px); }
/* Vibe Check beside the Track button: Track gets a little narrower so both fit on one row */
.close{
    position:fixed; top:20px; right:25px; width:36px; height:36px;
    border-radius:50%; background:transparent; border:transparent; color:#fff;
    font-size:38px; font-weight:bold; cursor:pointer; transition:all 0.25s ease;
    z-index:1000001; display:flex; align-items:center; justify-content:center; line-height:1;
    backdrop-filter:blur(8px); -webkit-backdrop-filter:blur(8px);
}
.close:hover{ background:rgba(255,0,0,0.25); border-color:rgba(255,0,0,0.4); color:var(--red); transform:scale(1.08); }
.close:active{ transform:scale(0.93); }
@media (max-width:768px){ .close{ display:none; } }

/* ══════════════════════════════════════
   VIBE CHECK — content inside the shared modal look above
══════════════════════════════════════ */
.vibe-result{
    display:none; text-align:center; padding:4px 16px 14px;
}
.vibe-result-label{ color:rgba(255,255,255,0.35); font-size:9.5px; letter-spacing:1px; text-transform:uppercase; margin:0 0 6px; }
.vibe-result-text{ color:#fff; font-size:17px; font-weight:700; margin:0; word-break:break-word; }
.vibe-result-total{ color:rgba(255,255,255,0.4); font-size:10.5px; margin:6px 0 0; }
.vibe-breakdown{ display:none; margin:12px auto 0; max-width:260px; text-align:left; }
.vibe-breakdown.show{ display:block; }
.vibe-bd-row{ display:flex; align-items:center; gap:8px; margin-top:7px; font-size:11px; color:rgba(255,255,255,.75); }
.vibe-bd-name{ flex:0 0 auto; max-width:46%; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.vibe-bd-bar{ flex:1; height:5px; border-radius:99px; background:rgba(255,255,255,.1); overflow:hidden; }
.vibe-bd-bar i{ display:block; height:100%; border-radius:99px; background:#FF2D2D; }
.vibe-bd-n{ flex:0 0 auto; min-width:14px; text-align:right; color:rgba(255,255,255,.5); font-size:10.5px; }

.vibe-grid{ display:grid; grid-template-columns:1fr 1fr; gap:6px; padding:2px 12px 14px; }
.vibe-opt{
    padding:9px 6px; border-radius:4px; border:none;
    background:rgba(255,255,255,0.05); color:rgba(255,255,255,0.85); font-size:11.5px;
    cursor:pointer; transition:background .2s ease, transform .15s ease;
    text-align:center; width:100%; line-height:1.35;
}
.vibe-opt:hover{ background:rgba(255,255,255,0.1); color:#fff; }
.vibe-opt:active{ transform:scale(.97); }
.vibe-opt.selected{ background:var(--red-dim); color:#fff; font-weight:600; box-shadow:inset 0 0 0 1.5px var(--red); }
.vibe-opt:disabled{ opacity:.5; pointer-events:none; }
/* UNDO my vote — boxy grey button, same look as the action buttons */
.vibe-undo-row{ display:none; padding:0 12px 14px; }
.vibe-undo{
    display:flex; align-items:center; justify-content:center; width:100%;
    height:var(--rp-action-h); border:none; border-radius:4px;
    background:rgba(255,255,255,0.1); color:#fff; font-size:11.5px; font-weight:600; font-family:inherit;
    transition:background .2s ease, color .2s ease, transform .15s ease;
}
.vibe-undo:hover{ background:rgba(255,255,255,0.2); color:var(--red); }
.vibe-undo:active{ transform:scale(.98); }
.vibe-undo:disabled{ opacity:.5; pointer-events:none; }

/* owner-only on/off switch row */
.vibe-owner{
    display:none; align-items:center; justify-content:space-between; gap:12px;
    padding:10px 16px 12px;
    border-top:1px solid rgba(255,255,255,0.08);
}
.vibe-owner-txt{ min-width:0; }
.vibe-owner-t{ font-size:12.5px; font-weight:600; color:#fff; }
.vibe-owner-s{ font-size:10.5px; color:rgba(255,255,255,0.45); margin-top:2px; line-height:1.4; }
.vibe-switch{
    position:relative; flex-shrink:0; width:44px; height:25px; border-radius:99px; border:none; padding:0;
    background:rgba(255,255,255,0.18); transition:background .22s ease;
}
.vibe-switch::after{
    content:''; position:absolute; top:3px; left:3px; width:19px; height:19px; border-radius:50%;
    background:#fff; transition:transform .22s ease;
}
.vibe-switch.on{ background:var(--red); }
.vibe-switch.on::after{ transform:translateX(19px); }
.vibe-switch:disabled{ opacity:.6; pointer-events:none; }

@media (max-width:790px){
    .vibe-result{ padding:2px 12px 10px; }
    .vibe-result-label{ font-size:8.5px; margin-bottom:4px; }
    .vibe-result-text{ font-size:15px; }
    .vibe-result-total{ font-size:9.5px; margin-top:4px; }
    .vibe-grid{ gap:5px; padding:2px 10px 10px; }
    .vibe-opt{ padding:7px 4px; font-size:10.5px; border-radius:4px; }
    .vibe-owner{ padding:8px 12px 10px; }
    .vibe-owner-t{ font-size:11.5px; }
    .vibe-owner-s{ font-size:9.5px; }
    .vibe-switch{ width:40px; height:23px; }
    .vibe-switch::after{ width:17px; height:17px; }
    .vibe-switch.on::after{ transform:translateX(17px); }
}

/* ══════════════════════════════════════
   EDIT PICTURE — content inside the shared modal look above
   (only used when the owner has NO posts yet — owners with posts get Dashboard)
══════════════════════════════════════ */
.ep-pic-wrap{
    width:96px; height:96px; margin:6px auto 12px; position:relative;
}
.ep-pic-wrap img{
    width:100%; height:100%; border-radius:50%; object-fit:cover; display:block;
    border:2px solid #FF2D2D;
}
#epFileInput{ display:none; }

.ep-row{
    display:flex; align-items:center; gap:10px; width:100%;
    padding:10px 14px; background:none; border:none;
    border-top:1px solid rgba(255,255,255,0.08);
    color:rgba(255,255,255,0.85); text-align:left; font-family:inherit;
    transition:background .2s;
}
.ep-row:hover{ background:rgba(255,255,255,0.06); }
.ep-row-ic{
    width:32px; height:32px; border-radius:50%; flex-shrink:0;
    border:1.5px dashed rgba(255,255,255,0.3);
    display:flex; align-items:center; justify-content:center;
}
.ep-row-ic i{ font-size:17px; color:rgba(255,255,255,0.6); }
.ep-row-t{ font-size:13px; font-weight:500; }

.ep-preview-area{
    display:none; flex-direction:column; align-items:center; gap:10px;
    padding:12px 14px 14px;
    border-top:1px solid rgba(255,255,255,0.08);
}
.ep-preview-area.visible{ display:flex; }
.ep-preview-area img{
    width:72px; height:72px; border-radius:50%; object-fit:cover;
    border:2px solid #FF2D2D;
}
.ep-preview-label{
    font-size:9px; color:rgba(255,255,255,0.35);
    text-transform:uppercase; letter-spacing:1px; font-weight:700;
}
.ep-preview-actions{ display:flex; gap:8px; width:100%; }
.ep-btn{
    flex:1; height:28px; border:none; border-radius:4px;
    font-size:.7rem; font-weight:700; font-family:inherit; line-height:1;
    transition:background .2s, transform .15s;
}
.ep-btn:active{ transform:scale(.98); }
.ep-btn.save{ background:var(--track-red); color:#000; }
.ep-btn.save:hover{ background:var(--track-red-hover); }
.ep-btn.save:disabled{ opacity:.5; pointer-events:none; }
.ep-btn.cancel{ background:rgba(255,255,255,0.1); color:#fff; }
.ep-btn.cancel:hover{ background:rgba(255,255,255,0.2); }

.ep-hint{
    text-align:center; font-size:10px; color:rgba(255,255,255,0.3);
    padding:10px 16px 12px; line-height:1.5;
    border-top:1px solid rgba(255,255,255,0.08);
}

/* Toast for the edit picture modal */
.ep-toast {
    position: fixed;
    bottom: 30px; left: 50%;
    transform: translateX(-50%) translateY(10px);
    background: rgba(8,8,22,.97);
    border: 1px solid rgba(255,45,45,.25);
    color: #fff; padding: 8px 20px; border-radius: 50px;
    font-size: 12px; font-family: 'Poppins', sans-serif; font-weight: 500;
    z-index: 9999999; pointer-events: none;
    box-shadow: 0 8px 28px rgba(0,0,0,.65);
    white-space: nowrap; opacity: 0;
    transition: opacity .22s ease, transform .22s ease;
}
.ep-toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

@media (max-width:790px){
    .ep-pic-wrap{ width:80px; height:80px; margin:4px auto 10px; }
    .ep-row{ padding:8px 12px; gap:9px; }
    .ep-row-ic{ width:27px; height:27px; }
    .ep-row-ic i{ font-size:15px; }
    .ep-row-t{ font-size:11.5px; }
    .ep-preview-area{ padding:10px 12px 12px; gap:8px; }
    .ep-preview-area img{ width:62px; height:62px; }
    .ep-btn{ height:26px; font-size:.64rem; }
    .ep-hint{ font-size:9px; padding:8px 12px 10px; }
}

/* ══════════════════════════════════════════════════════════════
   SHELL + RIGHT-HAND COLUMN (laptop / normal desktop view only)
   Same idea as the pod page: the profile lane sits on the LEFT and a
   sticky, independently-scrolling column of cards sits on the RIGHT.
   Below 1100px the column doesn't exist and nothing changes.
   The column now GROWS to fill the free space (no empty filler).
   ══════════════════════════════════════════════════════════════ */
.pf-shell{ width:100%; display:flex; align-items:flex-start; justify-content:center; }
.pf-side{ display:none; }

@media (min-width:1100px){
    .pf-shell{ justify-content:flex-start; padding-left:22px; }
    .rp-page{ margin:0; flex:0 0 var(--max-w); width:var(--max-w); }
    .pf-side{
        display:block; flex:1 1 0; min-width:0; max-width:720px;
        position:sticky; top:0; height:100vh; overflow-y:auto; overflow-x:hidden;
        padding:14px 26px 40px 22px;
        scrollbar-width:thin; scrollbar-color:rgba(255,255,255,.22) transparent;
    }
    .pf-side::-webkit-scrollbar{ width:5px; }
    .pf-side::-webkit-scrollbar-track{ background:transparent; }
    .pf-side::-webkit-scrollbar-thumb{ background:rgba(255,255,255,.22); border-radius:99px; }
    .pf-side::-webkit-scrollbar-thumb:hover{ background:rgba(255,255,255,.34); }
}


/* card order — change the numbers to re-order the column.
   Owner view: Top memes → Vibe → Insights → New trackers → … → Top post */
.pf-cards{ display:flex; flex-direction:column; }
.pf-sk-bar{ height:var(--rp-action-h); border-radius:var(--rp-action-radius); margin-bottom:0; }
.pf-sk-grid{ display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:4px; margin:8px 0 16px; }
.pf-sk-grid .dz-sk{ aspect-ratio:1; border-radius:4px; }
.pf-cards.pf-loaded{ animation:pfFade .3s ease both; }
@keyframes pfFade{ from{ opacity:0; transform:translateY(6px); } to{ opacity:1; transform:none; } }
.pf-card{ margin-bottom:14px; }
.pf-card[data-k="topmemes"]   { order:1; }
.pf-card[data-k="vibe"]       { order:2; }
.pf-card[data-k="insights"]   { order:3; }
.pf-card[data-k="newtrackers"]{ order:4; }
.pf-card[data-k="otd"]        { order:5; }
.pf-card[data-k="topcontrib"] { order:6; }
.pf-card[data-k="hashtags"]   { order:7; }
.pf-card[data-k="people"]     { order:8; }
.pf-card[data-k="toppost"]    { order:9; }
.pf-card[data-k="pending"]    { order:10; }
.pf-card[data-k="checklist"]  { order:11; }
.pf-card[data-k="locked"]     { order:1; }

/* the bubble bar — looks exactly like the action buttons: grey, no border */
.pf-bar{
    display:flex; align-items:center; gap:7px; width:100%;
    height:var(--rp-action-h); padding:0 12px;
    border:none; border-radius:var(--rp-action-radius);
    background:rgba(255,255,255,0.1);
    backdrop-filter:blur(10px); -webkit-backdrop-filter:blur(10px);
    color:#fff; font-size:.72rem; font-weight:600; line-height:1; text-align:left;
    transition:background .2s ease, transform .15s ease;
}
.pf-bar:hover{ background:rgba(255,255,255,0.2); }
.pf-bar:active{ transform:scale(.99); }
.pf-bar-ic{ font-size:14px; color:var(--red); flex-shrink:0; }
.pf-bar-t{ flex:1; min-width:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pf-bar-c{ font-size:.64rem; font-weight:600; color:rgba(255,255,255,.55); flex-shrink:0; }
.pf-bar-chev{ font-size:18px; color:rgba(255,255,255,.75); flex-shrink:0; transition:transform .25s ease; }
.pf-card.collapsed .pf-bar-chev{ transform:rotate(-90deg); }

.pf-body{ display:grid; grid-template-rows:1fr; transition:grid-template-rows .3s ease; }
.pf-inner{ min-height:0; overflow:hidden; }
.pf-pad{ padding-top:8px; }
.pf-card.collapsed .pf-body{ grid-template-rows:0fr; }

/* "See more / See less" + link bars — same grey bubble */
.pf-more{
    display:flex; align-items:center; justify-content:center; width:100%;
    height:var(--rp-action-h); margin-top:8px; padding:0 12px;
    border:none; border-radius:var(--rp-action-radius);
    background:rgba(255,255,255,0.1);
    backdrop-filter:blur(10px); -webkit-backdrop-filter:blur(10px);
    color:#fff; font-size:.7rem; font-weight:600; text-decoration:none; line-height:1;
    transition:background .2s ease, transform .15s ease;
}
.pf-more:hover{ background:rgba(255,255,255,0.2); }
.pf-more:active{ transform:scale(.98); }
.pf-more.red{ color:#000; background:var(--red); font-weight:700; }
.pf-more.red:hover{ background:#ff1a1a; }

/* square tiles (same look as the pod page's right grid) */
.pf-grid{ display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:4px; }
.pf-grid.one{ grid-template-columns:minmax(0,1fr); }
.pf-tile{
    position:relative; display:block; aspect-ratio:1; overflow:hidden; padding:0; border:none;
    border-radius:4px; background:#0d1030; text-align:left; width:100%;
}
.pf-grid.one .pf-tile{ aspect-ratio:1.15; }
.pf-tile img, .pf-tile video{
    position:absolute; inset:0; width:100%; height:100%; object-fit:cover; display:block;
    pointer-events:none; transition:transform .3s ease;
}
.pf-tile:hover img, .pf-tile:hover video{ transform:scale(1.06); }
/* text-only post → drawn on uploads/Text.jpg with the caption over it (same as the profile grid) */
.pf-tile-text{
    position:absolute; inset:0; padding:10px; display:flex; align-items:center; justify-content:center; text-align:center;
    font-size:.66rem; font-weight:500; line-height:1.45; color:#fff; word-break:break-word; overflow:hidden;
    background:#0d1030 url('uploads/Text.jpg') center / cover no-repeat;
}
.pf-tile-text::before{
    content:''; position:absolute; inset:0; background:rgba(0,0,0,0.45); pointer-events:none;
}
.pf-tile-text span{
    position:relative; z-index:1;
    display:-webkit-box; -webkit-line-clamp:6; -webkit-box-orient:vertical; overflow:hidden;
    text-shadow:0 1px 4px rgba(0,0,0,0.6);
}
.pf-tile-vid{
    position:absolute; top:6px; right:6px; z-index:2; width:20px; height:20px; border-radius:6px;
    background:rgba(0,0,0,.55); color:#fff; display:flex; align-items:center; justify-content:center; font-size:12px; pointer-events:none;
}
.pf-rank{
    position:absolute; top:6px; left:6px; z-index:2; padding:2px 7px; border-radius:6px;
    background:rgba(0,0,0,.6); color:#fff; font-size:.6rem; font-weight:700; letter-spacing:.2px; pointer-events:none;
}
.pf-tile-ov{
    position:absolute; inset:0; z-index:1; display:flex; align-items:center; justify-content:center; gap:12px;
    background:rgba(2,3,20,.55); color:#fff; font-size:.68rem; font-weight:700;
    opacity:0; transition:opacity .2s ease; pointer-events:none;
}
.pf-tile:hover .pf-tile-ov{ opacity:1; }
.pf-tile-ov span{ display:inline-flex; align-items:center; gap:4px; }
.pf-tile-ov i{ font-size:.85rem; }

/* people grid (Mutuals / Circle) */
.pf-utile{
    position:relative; display:block; aspect-ratio:1; overflow:hidden; border-radius:4px; background:#0d1030; text-decoration:none;
}
.pf-utile img{ position:absolute; inset:0; width:100%; height:100%; object-fit:cover; display:block; transition:transform .3s ease; }
.pf-utile:hover img{ transform:scale(1.06); }
.pf-utile span{
    position:absolute; left:0; right:0; bottom:0; padding:16px 6px 5px; color:#fff; font-size:.62rem; font-weight:600;
    background:linear-gradient(180deg,transparent,rgba(0,0,0,.8)); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; text-align:center;
}

/* list rows (pods, visitors, trackers, requests) */
.pf-row{
    display:flex; align-items:center; gap:10px; padding:8px 2px; color:#fff; text-decoration:none;
    border-bottom:1px solid rgba(255,255,255,.06);
}
.pf-row:last-of-type{ border-bottom:none; }
a.pf-row:hover .pf-row-t{ text-decoration:underline; }
.pf-hold{ display:none; }
.pf-in{ animation:pfRowIn .3s cubic-bezier(.22,1,.36,1) both; }
@keyframes pfRowIn{ from{ opacity:0; transform:translateY(6px); } to{ opacity:1; transform:none; } }
.pf-av{ width:34px; height:34px; border-radius:50%; object-fit:cover; border:1.5px solid var(--red); flex-shrink:0; }
.pf-av.sq{ border-radius:8px; }
.pf-row-info{ flex:1; min-width:0; }
.pf-row-t{ font-size:.76rem; font-weight:600; color:#fff; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pf-row-s{ font-size:.64rem; color:rgba(255,255,255,.5); margin-top:2px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pf-row-end{ font-size:.9rem; color:var(--red); flex-shrink:0; }

/* chips (hashtags, runner-up vibes) */
.pf-chips{ display:flex; flex-wrap:wrap; gap:6px; }
.pf-chip{
    display:inline-flex; align-items:center; gap:5px; padding:5px 10px; border-radius:var(--rp-action-radius);
    background:rgba(255,255,255,.07); color:#fff; font-size:.68rem; font-weight:600; text-decoration:none; line-height:1;
    transition:background .2s ease;
}
a.pf-chip:hover{ background:rgba(255,255,255,.16); }
.pf-chip b{ color:rgba(255,255,255,.55); font-weight:600; font-size:.62rem; }

/* vibe */
.pf-vibe{ text-align:center; padding:6px 4px 2px; }
.pf-vibe-lbl{ font-size:.6rem; letter-spacing:1px; text-transform:uppercase; color:rgba(255,255,255,.45); margin-bottom:6px; }
.pf-vibe-top{ font-size:1.05rem; font-weight:700; color:#fff; line-height:1.3; word-break:break-word; }
.pf-vibe-sub{ font-size:.66rem; color:rgba(255,255,255,.45); margin-top:5px; }
.pf-vibe .pf-chips{ justify-content:center; margin-top:10px; }
.pf-note{ font-size:.68rem; color:rgba(255,255,255,.5); line-height:1.5; text-align:center; padding:4px 6px; }

.pf-vibe-toggle{
    display:flex; align-items:center; justify-content:space-between; gap:12px;
    margin-top:10px; padding:8px 12px; border-radius:var(--rp-action-radius);
    background:rgba(255,255,255,.05);
}
.pf-vibe-toggle-t{ font-size:.7rem; font-weight:600; color:#fff; }

/* insights big number */
.pf-stat{ display:flex; align-items:baseline; gap:8px; padding:2px 2px 8px; }
.pf-stat b{ font-size:1.5rem; font-weight:700; color:#fff; line-height:1; }
.pf-stat span{ font-size:.68rem; color:rgba(255,255,255,.55); }

/* top-performing post stats */
.pf-post-stats{ display:flex; align-items:center; gap:14px; padding:8px 2px 0; font-size:.7rem; font-weight:600; color:#fff; }
.pf-post-stats span{ display:inline-flex; align-items:center; gap:5px; }
.pf-post-stats i{ color:var(--red); font-size:.9rem; }

/* checklist */
.pf-prog{ height:5px; border-radius:99px; background:rgba(255,255,255,.1); overflow:hidden; margin:2px 2px 8px; }
.pf-prog i{ display:block; height:100%; border-radius:99px; background:var(--red); transition:width .4s ease; }
.pf-check{
    display:flex; align-items:center; gap:10px; padding:8px 2px; text-decoration:none; color:#fff;
    border-bottom:1px solid rgba(255,255,255,.06);
}
.pf-check:last-child{ border-bottom:none; }
.pf-check .ck{ font-size:1.05rem; color:rgba(255,255,255,.3); flex-shrink:0; }
.pf-check.done .ck{ color:#4ade80; }
.pf-check.done .tx{ color:rgba(255,255,255,.45); text-decoration:line-through; }
.pf-check .tx{ flex:1; font-size:.74rem; font-weight:500; }
.pf-check .go{ font-size:1rem; color:rgba(255,255,255,.4); }
a.pf-check:hover .go{ color:#fff; }

/* ══════════════════════════════════════════════════════════════════════════
   PROFILE CONTENT — tabs, sort bar, Collections, Messages, empty states
   (all CSS for the grid / messages area lives here — none is inline)
══════════════════════════════════════════════════════════════════════════ */

/* ══════════════════════════════════════════════════════════
   TAB PAGER — the tab panels sit side by side and follow your finger,
   exactly like the Tracks page. The pager (not CSS display rules on the
   panels) decides which panel is visible, so the old
   `.dropdown-section{display:none}` rules are gone.
   Keep these properties exactly as they are:
   • display:none on idle, inactive panels → correct page height, hidden
     videos never play, hidden images never load.
   • NO will-change / transform while idle → a transform on the track would
     break position:fixed elements inside a panel (collection menus etc).
   • overflow-x:clip, not hidden → hidden would make the pager a scroll
     container and break sticky behaviour.
══════════════════════════════════════════════════════════ */
.rp-pager{ width:100%; position:relative; touch-action:pan-y; }
@supports (overflow:clip){ .rp-pager{ overflow-x:clip; } }
@supports not (overflow:clip){ .rp-pager{ overflow:hidden; } }
.rp-pager.dragging{ user-select:none; -webkit-user-select:none; cursor:grabbing; }
.rp-pager img{ -webkit-user-drag:none; }
.rp-track{ display:flex; align-items:flex-start; width:100%; }
.rp-pager:not(.idle) .rp-track{ will-change:transform; backface-visibility:hidden; }
.rp-track > .dropdown-section{ display:block !important; flex:0 0 100%; width:100%; min-width:0; }
.rp-pager.idle .rp-track > .dropdown-section:not(.rp-active){ display:none !important; }

.meme-card .caption i{ color:#FF4C4C; }

/* ══════════════════════════════════════════════════════════
   SORT + COLLECTIONS BAR  (Newest | Popular | Oldest | Collections)
   and the Messages filter bar (All | Unread | Dry Chat | Requests)
   ONE set of rules for BOTH bars so size, weight and height always match.
══════════════════════════════════════════════════════════ */
.grid-sort-bar,
.msg-filter-bar{
    --tab-btn-h: clamp(22px, 6vw, 25.5px);
    --tab-btn-radius: 4px;
    --tab-btn-bg: rgba(255,255,255,0.075);
    --tab-btn-bg-hover: rgba(255,255,255,0.15);
    display:flex; align-items:center; justify-content:flex-start;
    flex-wrap:nowrap; gap:clamp(6px, 1.6vw, 8px);
    width:100%; max-width:var(--max-w); margin:0 auto;
    padding:10px var(--rp-header-pad-x);
    border:none;
    overflow-x:auto; scrollbar-width:none; -ms-overflow-style:none;
    -webkit-overflow-scrolling:touch;
}
.grid-sort-bar::-webkit-scrollbar,
.msg-filter-bar::-webkit-scrollbar{ display:none; }

.g-pill,
.msg-pill{
    flex:0 0 auto; width:auto; min-width:0;
    position:relative;
    display:inline-flex; align-items:center; justify-content:center; gap:clamp(3px, 1.2vw, 6px);
    height:var(--tab-btn-h); padding:0 clamp(9px, 2.5vw + 1px, 16px); line-height:1;
    border:none; border-radius:var(--tab-btn-radius);
    background:var(--tab-btn-bg);
    backdrop-filter:blur(10px); -webkit-backdrop-filter:blur(10px);
    box-shadow:none;
    color:#fff; font-family:Poppins,sans-serif;
    font-size:clamp(.57rem, .35rem + 1.1vw, .72rem); font-weight:600;
    white-space:nowrap; cursor:pointer;
    transition:background .2s ease, color .2s ease, transform .15s ease;
    -webkit-tap-highlight-color:transparent;
}
.g-pill *:not(i),
.msg-pill *:not(i){
    font-family:inherit !important;
    font-size:inherit !important;
    font-weight:inherit !important;
    line-height:1;
}
.g-pill i,
.msg-pill i{ font-size:clamp(11px, 1.6vw + 5px, 14px) !important; margin-right:0 !important; }

.g-pill:hover,
.msg-pill:hover{ background:var(--tab-btn-bg-hover); color:#fff; border:none; }
.g-pill:active,
.msg-pill:active{ transform:scale(0.98); }

.g-pill.active,
.msg-pill.active,
.g-pill.active:hover,
.msg-pill.active:hover{
    background:var(--tab-btn-bg);
    color:#FF2D2D;
    font-weight:800;
    border:none; box-shadow:none;
}

.g-pill .g-pill-count,
.msg-pill .req-badge,
.g-pill.active .g-pill-count,
.msg-pill.active .req-badge{
    display:inline-block; background:none; border-radius:0; padding:0; min-width:0; height:auto;
    color:#fff !important; margin-left:2px; line-height:1; letter-spacing:0;
}
.g-pill-count:empty{ display:none; }


/* ══════════════════════════════════════════════════════════
   EMPTY STATES — same design as the Untracked page.
   Used by every empty grid (different words for the profile owner and for a
   visitor), by the empty inbox, AND by the private-profile / blocked screens.
══════════════════════════════════════════════════════════ */
.es-wrap{
    grid-column:1/-1; width:100%; min-height:46vh;
    padding:clamp(28px, 8vw, 48px) clamp(20px, 7vw, 36px) clamp(36px, 10vw, 60px);
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    text-align:center;
}
.es-title{ font-size:clamp(.95rem, 3.4vw, 1.1rem); font-weight:700; color:#fff; letter-spacing:-.2px; }
.es-text{
    margin-top:6px; max-width:340px;
    font-size:clamp(.66rem, 2.1vw, .76rem); color:var(--muted); line-height:1.7;
}
.es-tips{
    width:100%; max-width:360px;
    margin-top:clamp(16px, 5vw, 24px);
    display:flex; flex-direction:column; gap:7px;
}
.es-tip{
    display:flex; align-items:center; gap:10px;
    padding:10px 12px; border-radius:var(--rp-action-radius);
    background:rgba(255,255,255,0.05);
    text-align:left;
}
.es-tip i{ font-size:1rem; color:var(--red); flex-shrink:0; }
.es-tip span{ font-size:clamp(.62rem, 2vw, .7rem); color:rgba(255,255,255,0.62); line-height:1.5; }
.es-btn{
    margin-top:clamp(16px, 5vw, 22px);
    display:flex; align-items:center; justify-content:center;
    height:var(--rp-action-h); min-width:150px; padding:0 22px;
    border-radius:var(--rp-action-radius);
    background:rgba(255,255,255,0.1); color:#fff;
    font-size:clamp(.62rem, .5rem + .5vw, .72rem); font-weight:600; text-decoration:none;
    transition:background .2s ease, transform .15s ease;
}
.es-btn:hover{ background:rgba(255,255,255,0.2); }
.es-btn:active{ transform:scale(0.98); }

/* ── buttons inside the empty / private / blocked states (boxy, same as the action buttons) ── */
button.es-btn{ border:none; font-family:'Poppins',sans-serif; cursor:pointer; }
.es-btn.track{ background:var(--track-red); color:#000; font-weight:700; }
.es-btn.track:hover{ background:var(--track-red-hover); }
.es-form{ margin:0; display:flex; justify-content:center; }

/* ── Messages empty states: .msg-empty-wrap wraps a normal .es-wrap.
   The JS toggles display inline and only one shows at a time. ── */
.msg-empty-wrap{ width:100%; }
.msg-empty-wrap .es-wrap{ min-height:38vh; }   /* shorter than the grid tabs because the filter bar sits above it */
/* .msg-list has its own side padding, .es-wrap already has some — cancel the doubling */
.msg-list > .msg-empty-wrap{ margin:0 calc(var(--rp-header-pad-x) * -1); width:calc(100% + var(--rp-header-pad-x) * 2); }
.msg-list > .es-wrap{ margin:0 calc(var(--rp-header-pad-x) * -1); width:calc(100% + var(--rp-header-pad-x) * 2); }

.col-section{ display:none; padding-top:4px; }

.col-search-wrap{ position:relative; margin:6px var(--rp-header-pad-x) 12px; }
.col-search-input{
    width:100%; background:rgba(255,255,255,0.06); border:none;
    border-radius:4px; padding:clamp(6px, 1.5vw, 10px) clamp(26px, 1.7vw + 20px, 34px) clamp(6px, 1.5vw, 10px) clamp(10px, 1vw + 7px, 14px); color:#fff; font-size:clamp(10px, 8px + .5vw, 12px);
    font-family:Poppins,sans-serif; outline:none; transition:background .2s; box-sizing:border-box;
}
.col-search-input:focus{ background:rgba(255,255,255,0.1); }
.col-search-input::placeholder{ color:rgba(255,255,255,0.25); }
.col-search-icon{ display:none !important; }
.col-search-clear{ position:absolute; right:12px; top:50%; transform:translateY(-50%); font-size:13px; color:rgba(255,255,255,0.3); cursor:pointer; display:none; background:none; border:none; padding:0; line-height:1; }
.col-search-clear:hover{ color:rgba(255,255,255,0.7); }

.col-folders-grid{
    display:grid; grid-template-columns:repeat(auto-fill,minmax(clamp(140px, 28vw, 165px),1fr)); gap:clamp(8px, 2vw, 14px);
    padding:18px var(--rp-header-pad-x) 20px; row-gap:clamp(24px, 6vw, 30px);
}
.col-folders-grid > .es-wrap, .col-detail .grid > .es-wrap{ grid-column:1/-1; }
.col-folder-card{ border-radius:8px; background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); overflow:hidden; cursor:pointer; transition:all .25s; position:relative;
    /* two more grey "cards" peeking out from behind the top edge, so every collection looks like a small stack */
    box-shadow:0 -8px 0 -3px #2b2c3f, 0 -15px 0 -6px #1d1e30; }
.col-folder-card:hover{ border-color:rgba(255,45,45,0.35); transform:translateY(-2px); box-shadow:0 -8px 0 -3px #33344a, 0 -15px 0 -6px #222338, 0 8px 22px rgba(0,0,0,0.3); }
.col-folder-card.is-public{ border-color:rgba(255,85,102,0.2); }
.col-folder-card.is-pinned-col{ border-color:rgba(255,45,45,0.5); box-shadow:0 -8px 0 -3px #2b2c3f, 0 -15px 0 -6px #1d1e30, 0 0 18px rgba(255,45,45,0.12); }
.col-folder-preview{ width:100%; aspect-ratio:1; display:grid; grid-template-columns:1fr 1fr; grid-template-rows:1fr 1fr; gap:2px; background:rgba(255,255,255,0.03); overflow:hidden; }
.col-fp-item{ background:rgba(255,255,255,0.06); overflow:hidden; display:flex; align-items:center; justify-content:center; }
.col-fp-item img,.col-fp-item video{ width:100%; height:100%; object-fit:cover; display:block; }
.col-fp-empty{ background:rgba(255,255,255,0.04); display:flex; align-items:center; justify-content:center; }
.col-fp-empty i{ font-size:14px; color:rgba(255,255,255,0.08); }
.col-folder-info{ padding:10px 12px; }
.col-folder-name{ font-size:clamp(12px, 1vw + 7.5px, 13px); font-weight:600; color:#fff; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; margin-bottom:3px; }
.col-folder-count{ font-size:11px; color:rgba(255,255,255,0.4); margin-bottom:5px; }
.col-folder-timeline{ display:flex; flex-direction:column; gap:2px; border-top:1px solid rgba(255,255,255,0.06); padding-top:6px; margin-top:4px; }
.col-folder-tl-row{ font-size:9.5px; color:rgba(255,255,255,0.28); display:flex; align-items:center; gap:4px; letter-spacing:.1px; }
.col-folder-tl-row i{ font-size:10px; flex-shrink:0; color:rgba(255,255,255,0.2); }
.col-folder-tl-row span{ white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.col-folder-vis{ font-size:10px; font-weight:600; margin-top:5px; display:flex; align-items:center; gap:3px; letter-spacing:.3px; }
.col-folder-vis.pub{ color:#4dde8a; }
.col-folder-vis.priv{ color:rgba(255,255,255,0.3); }
.col-folder-opts{ position:absolute; top:8px; right:8px; width:28px; height:28px; border-radius:50%; background:rgba(0,0,0,0.6); backdrop-filter:blur(8px); border:none; color:#fff; font-size:14px; display:flex; align-items:center; justify-content:center; cursor:pointer; opacity:0; transition:opacity .2s; z-index:5; -webkit-tap-highlight-color:transparent; }
.col-folder-card:hover .col-folder-opts{ opacity:1; }
@media(max-width:768px){ .col-folder-opts{ opacity:1; } }
.col-new-btn{ border-radius:6px; background:rgba(255,45,45,0.07); border:1.5px dashed rgba(255,45,45,0.3); cursor:pointer; transition:all .25s; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:8px; min-height:clamp(120px, 32vw, 150px); color:rgba(255,85,102,0.7); font-family:Poppins,sans-serif; font-size:clamp(11px, 2vw + 2px, 12px); font-weight:600; -webkit-tap-highlight-color:transparent; width:100%; order:-1; }
.col-new-btn:hover{ border-color:rgba(255,45,45,0.6); color:rgba(255,85,102,1); background:rgba(255,45,45,0.12); }
.col-new-btn i{ font-size:26px; }

.col-public-badge{ position:absolute; top:8px; left:8px; background:rgba(0,0,0,0.65); backdrop-filter:blur(8px); border:1px solid rgba(77,222,138,0.45); border-radius:20px; padding:3px 8px; font-size:9px; font-weight:700; color:#4dde8a; letter-spacing:.5px; text-transform:uppercase; z-index:5; pointer-events:none; }
.col-pin-badge{ position:absolute; top:8px; left:8px; background:rgba(0,0,0,0.65); backdrop-filter:blur(8px); border:1px solid rgba(255,45,45,0.5); border-radius:20px; padding:3px 8px; font-size:9px; font-weight:700; color:#ff5566; letter-spacing:.5px; z-index:5; pointer-events:none; }
.col-pin-badge.with-pub{ top:30px; }

/* ══ COLLECTION DETAIL ══ */
.col-detail{ display:none; }
.col-detail-hdr{ display:flex; align-items:center; gap:12px; padding:6px var(--rp-header-pad-x) 12px; }
.col-back-btn{ width:clamp(22px, 6vw, 30px); height:clamp(22px, 6vw, 30px); border-radius:6px; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.1); color:#fff; font-size:clamp(11px, 1.8vw + 4px, 14px); display:flex; align-items:center; justify-content:center; cursor:pointer; flex-shrink:0; transition:all .2s; -webkit-tap-highlight-color:transparent; }
.col-back-btn:hover{ background:rgba(255,45,45,0.15); border-color:rgba(255,45,45,0.4); }
.col-detail-title{ font-size:clamp(11.5px, 1vw + 7px, 12.5px); font-weight:600; color:#fff; flex:1; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.col-detail-count{ font-size:12px; color:rgba(255,255,255,0.4); flex-shrink:0; }

.col-detail-search-wrap{ position:relative; margin:6px var(--rp-header-pad-x) 12px; }
.col-detail-search-input{
    width:100%; background:rgba(255,255,255,0.06); border:none;
    border-radius:4px; padding:clamp(6px, 1.5vw, 10px) clamp(26px, 1.7vw + 20px, 34px) clamp(6px, 1.5vw, 10px) clamp(10px, 1vw + 7px, 14px); color:#fff; font-size:clamp(10px, 8px + .5vw, 12px);
    font-family:Poppins,sans-serif; outline:none; transition:background .2s; box-sizing:border-box;
}
.col-detail-search-input:focus{ background:rgba(255,255,255,0.1); }
.col-detail-search-input::placeholder{ color:rgba(255,255,255,0.25); }
.col-detail-search-icon{ display:none !important; }
.col-detail-search-clear{ position:absolute; right:12px; top:50%; transform:translateY(-50%); font-size:13px; color:rgba(255,255,255,0.3); cursor:pointer; display:none; background:none; border:none; padding:0; line-height:1; }
.col-detail-search-clear:hover{ color:rgba(255,255,255,0.7); }
.col-detail-no-results{ grid-column:1/-1; text-align:center; padding:30px 20px; color:rgba(255,255,255,0.3); font-size:13px; display:none; }
.col-detail-no-results i{ font-size:2rem; display:block; margin-bottom:8px; color:rgba(255,85,102,0.35); }

/* ══ BUTTONS ON A CARD ══ */
.card-add-col-btn{ position:absolute; bottom:8px; right:8px; width:32px; height:32px; border-radius:50%; background:rgba(0,0,0,0.65); backdrop-filter:blur(8px); border:1px solid rgba(255,255,255,0.18); color:#fff; font-size:15px; display:flex; align-items:center; justify-content:center; cursor:pointer; z-index:5; transition:all .2s; -webkit-tap-highlight-color:transparent; }
.card-add-col-btn:hover{ background:rgba(255,45,45,0.75); border-color:transparent; transform:scale(1.1); }
.card-pin-btn{ background:none; border:none; color:rgba(255,255,255,0.4); font-size:16px; display:flex; align-items:center; justify-content:center; cursor:pointer; padding:0 2px; transition:color .2s; -webkit-tap-highlight-color:transparent; line-height:1; }
.card-pin-btn:hover{ color:rgba(255,85,102,0.85); }
.meme-card.dz-lp{ -webkit-touch-callout:none; -webkit-user-select:none; user-select:none; }
.meme-card.dz-lp-arm{ transform:scale(.97); transition:transform .25s linear; }
.card-pin-btn.pinned{ color:#ff2d2d; }
.card-pin-indicator{ position:absolute; top:10px; right:50px; font-size:14px; color:#ff2d2d; pointer-events:none; z-index:6; filter:drop-shadow(0 1px 3px rgba(0,0,0,0.7)); }
.card-remove-btn{ position:absolute; bottom:8px; right:8px; width:32px; height:32px; border-radius:50%; background:rgba(180,0,0,0.75); backdrop-filter:blur(8px); border:none; color:#fff; font-size:15px; display:flex; align-items:center; justify-content:center; cursor:pointer; z-index:5; transition:all .2s; -webkit-tap-highlight-color:transparent; }
.card-remove-btn:hover{ background:rgba(255,0,0,0.95); transform:scale(1.1); }

/* ══ TOAST + small states ══ */
.g-toast{ position:fixed; bottom:90px; left:50%; transform:translateX(-50%); background:rgba(14,14,30,0.97); border:1px solid rgba(255,45,45,0.3); color:#fff; padding:9px 24px; border-radius:50px; font-size:12px; font-family:Poppins,sans-serif; z-index:99999999; pointer-events:none; box-shadow:0 8px 24px rgba(0,0,0,0.6); white-space:nowrap; }
.g-toast-in{ animation:toastIn .25s ease forwards; }
@keyframes toastIn{ from{ opacity:0; transform:translateX(-50%) translateY(8px); } to{ opacity:1; transform:translateX(-50%) translateY(0); } }
.col-visitor-empty{ grid-column:1/-1; text-align:center; padding:40px 20px; color:rgba(255,255,255,0.3); font-size:13px; }
.col-visitor-empty i{ font-size:2.5rem; display:block; margin-bottom:10px; color:rgba(255,85,102,0.4); }
.col-search-no-results{ grid-column:1/-1; text-align:center; padding:30px 20px; color:rgba(255,255,255,0.3); font-size:13px; display:none; }
.col-search-no-results i{ font-size:1.8rem; display:block; margin-bottom:8px; color:rgba(255,85,102,0.3); }
@keyframes spin{ to{ transform:rotate(360deg); } }

/* ══ COLLECTIONS RESPONSIVE ══ */
/* ══════════════════════════════════════════════════════════
   MESSAGES TAB
   Radius tokens for the whole tab: 4px for small controls, 6px for cards / rows.
══════════════════════════════════════════════════════════ */
.msg-search-wrap{ position:relative; margin:6px var(--rp-header-pad-x) 12px; }
.msg-search-input{
    width:100%; background:rgba(255,255,255,0.06); border:none;
    border-radius:4px; padding:clamp(6px, 1.5vw, 10px) clamp(26px, 1.7vw + 20px, 34px) clamp(6px, 1.5vw, 10px) clamp(10px, 1vw + 7px, 14px); color:#fff; font-size:clamp(10px, 8px + .5vw, 12px);
    font-family:Poppins,sans-serif; outline:none; transition:background .2s; box-sizing:border-box;
}
.msg-search-input:focus{ background:rgba(255,255,255,0.1); }
.msg-search-input::placeholder{ color:rgba(255,255,255,0.25); }
.msg-search-icon{ display:none !important; }
.msg-search-clear{ position:absolute; right:12px; top:50%; transform:translateY(-50%); font-size:13px; color:rgba(255,255,255,0.3); cursor:pointer; display:none; background:none; border:none; padding:0; line-height:1; }
.msg-search-clear:hover{ color:rgba(255,255,255,0.7); }

.msg-list{ display:flex; flex-direction:column; padding:0 var(--rp-header-pad-x); }

/* message requests */
.msg-request-item{
    display:flex; align-items:center; gap:clamp(8px, 2.2vw, 12px);
    background:rgba(255,45,45,0.07); border:none;
    padding:clamp(7px, 2vw, 10px) clamp(9px, 2.8vw, 15px); border-radius:6px; margin-bottom:6px;
    transition:background .2s, opacity .3s, transform .3s;
}
.msg-request-item:hover{ background:rgba(255,45,45,0.1); }
.msg-request-item.msg-req-out-right{ opacity:0; transform:translateX(20px); }
.msg-request-item.msg-req-out-left{ opacity:0; transform:translateX(-20px); }
.msg-request-item img{ width:clamp(32px, 4.5vw + 17px, 44px); height:clamp(32px, 4.5vw + 17px, 44px); border-radius:50%; object-fit:cover; border:2px solid #FF2D2D !important; flex-shrink:0; cursor:pointer; }
.msg-request-info{ flex:1; min-width:0; cursor:pointer; }
.msg-request-name{ font-size:clamp(11px, 1vw + 7.5px, 13px); font-weight:600; color:#fff; display:flex; align-items:center; gap:6px; margin-bottom:2px; flex-wrap:wrap; }
.msg-request-tag{ font-size:9px; font-weight:700; padding:2px 6px; border-radius:4px; background:rgba(255,45,45,0.15); border:1px solid rgba(255,45,45,0.3); color:#ff5566; letter-spacing:.3px; }
.msg-req-count{ background:#FF4C4C; color:#fff; font-size:8px; font-weight:700; padding:1px 5px; border-radius:4px; }
.msg-request-preview{ font-size:clamp(9.5px, .6vw + 7px, 11px); color:rgba(255,255,255,0.4); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.msg-deleted-req{ color:rgba(255,255,255,0.25); }
.msg-request-actions{ display:flex; flex-direction:column; gap:5px; flex-shrink:0; }
.msg-req-accept{ padding:clamp(3px, .5vw + 1.5px, 5px) clamp(8px, 1vw + 5px, 12px); border-radius:4px; background:rgba(77,222,138,0.15); border:1px solid rgba(77,222,138,0.35); color:#4dde8a; font-size:clamp(8px, .4vw + 7px, 10px); font-weight:700; cursor:pointer; font-family:Poppins,sans-serif; transition:background .2s; white-space:nowrap; }
.msg-req-accept:hover{ background:rgba(77,222,138,0.25); }
.msg-req-decline{ padding:clamp(3px, .5vw + 1.5px, 5px) clamp(8px, 1vw + 5px, 12px); border-radius:4px; background:rgba(255,45,45,0.1); border:1px solid rgba(255,45,45,0.25); color:rgba(255,255,255,0.4); font-size:clamp(8px, .4vw + 7px, 10px); font-weight:700; cursor:pointer; font-family:Poppins,sans-serif; transition:background .2s; white-space:nowrap; }
.msg-req-decline:hover{ background:rgba(255,45,45,0.18); color:#ff5566; }

.msg-requests-section{ display:none; padding:14px var(--rp-header-pad-x) 0; }
.msg-requests-section.active{ display:block; }
.msg-requests-header{ font-size:10px; font-weight:700; color:rgba(255,255,255,0.3); text-transform:uppercase; letter-spacing:1px; padding:0 2px 10px; display:flex; align-items:center; gap:5px; }
.msg-requests-header i{ font-size:10px; }

/* conversation rows */
.message-user{
    display:flex; align-items:center; gap:clamp(8px, 2vw, 12px); padding:clamp(6px, 1.2vw + 2px, 10px) clamp(8px, 1.8vw + 2px, 12px); cursor:pointer;
    background:rgba(255,255,255,0.06); border:none;
    transition:background .2s ease; border-radius:6px; margin-bottom:6px;
}
.message-user:hover{ background:rgba(255,255,255,0.1); }
.message-user img{ width:clamp(32px, 5vw + 16px, 48px); height:clamp(32px, 5vw + 16px, 48px); border-radius:50%; object-fit:cover; flex-shrink:0; border:2px solid #FF2D2D !important; }
.gstack{position:relative;display:block;width:clamp(32px, 5vw + 16px, 48px);height:clamp(32px, 5vw + 16px, 48px);flex-shrink:0}
.message-user .gstack img{position:absolute;width:62%;height:62%;border-radius:50%;object-fit:cover;border:2px solid #FF2D2D !important;box-sizing:border-box;background:#10143a}
.gstack.n3 img:nth-child(1){left:19%;top:0;z-index:3}
.gstack.n3 img:nth-child(2){left:0;bottom:0;z-index:2}
.gstack.n3 img:nth-child(3){right:0;bottom:0;z-index:1}
.gstack.n2 img:nth-child(1){left:0;top:0;z-index:2}
.gstack.n2 img:nth-child(2){right:0;bottom:0;z-index:1}
.message-user .gstack.n1 img{width:100%;height:100%}
.message-user-info{ display:flex; flex-direction:column; flex:1; min-width:0; }
.message-user-name{ font-size:clamp(.68rem, .55rem + .5vw, .86rem); font-weight:600; color:#fff; display:flex; align-items:center; gap:5px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.message-user-preview{ font-size:clamp(.6rem, .48rem + .45vw, .76rem); color:rgba(255,255,255,0.5); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; margin-top:3px; }
.message-unread-badge{ background:#f24455; color:#fff; min-width:clamp(12px, 1.2vw + 8px, 18px); height:clamp(12px, 1.2vw + 8px, 18px); border-radius:4px; display:flex; align-items:center; justify-content:center; padding:0 clamp(3px, .5vw + 1px, 5px); flex-shrink:0; font-size:clamp(8px, .4vw + 7px, 10px); font-weight:700; }
.msg-seen{ color:#227cd6; font-size:10px; font-weight:600; margin-left:4px; letter-spacing:.2px; }
.msg-unread-pill{ background:#FF4C4C; color:#fff; font-size:9px; font-weight:700; padding:1px 6px; border-radius:4px; margin-left:4px; }
.msg-dry-tag{ font-size:9px; color:rgba(255,255,255,0.25); font-weight:600; letter-spacing:.3px; flex-shrink:0; }
.msg-you{ color:#d62222; font-weight:500; }
.msg-deleted{ color:rgba(255,255,255,0.3); font-style:italic; }
.msg-att-ico{ color:#2231d6; font-size:13px; vertical-align:-2px; }

/* ══ TAB PAGER (moved up from the body) ══ */
.rp-pager{ width:100%; position:relative; touch-action:pan-y; }
@supports (overflow:clip){ .rp-pager{ overflow-x:clip; } }
@supports not (overflow:clip){ .rp-pager{ overflow:hidden; } }
.rp-pager.dragging{ user-select:none; -webkit-user-select:none; cursor:grabbing; }
.rp-pager img{ -webkit-user-drag:none; }
.rp-track{ display:flex; align-items:flex-start; width:100%; }
.rp-pager:not(.idle) .rp-track{ will-change:transform; backface-visibility:hidden; }
.rp-track > .dropdown-section{ display:block !important; flex:0 0 100%; width:100%; min-width:0; }
.rp-pager.idle .rp-track > .dropdown-section:not(.rp-active){ display:none !important; }
.rp-tab-indicator.live{ transition:none !important; }
/* the pin button lives inside .card-badges, which ignores the pointer — give the button its own */
.grid .meme-card .card-badges .card-pin-btn{ pointer-events:auto; }

/* ══ small blocks moved up from inline styles in the body ══ */
.dz-fx1{ flex:1; min-width:0; }
.dz-fx1b{ flex:1; }
.dz-ptr{ cursor:pointer; }
.dz-sent1{ height:1px; }
.dz-blue{ color:#2b67f5; }
.dz-chk{ color:#2b67f5; font-size:16px; flex-shrink:0; }
.ukb-add-row.dz-add-off{ color:rgba(255,255,255,0.25); cursor:not-allowed; }
.ukb-add-icon.dz-addic-off{ border:1.5px dashed rgba(255,255,255,0.15); }
.ukb-add-icon.dz-addic-on{ border:1.5px dashed rgba(255,255,255,0.3); }
.dz-addi-off{ font-size:18px; color:rgba(255,255,255,0.2); }
.dz-addi-on{ font-size:18px; color:rgba(255,255,255,0.5); }
.dz-addt{ font-size:13px; font-weight:500; display:block; }
.dz-addlim{ font-size:10px; color:rgba(255,255,255,0.25); }
.rp-tab-btn[data-panel="messages"]{ position:relative; }

.rp-profile-type.is-link{ cursor:pointer; -webkit-tap-highlight-color:transparent; transition:color .2s; }
.rp-profile-type.is-link:hover{ color:#fff; }
.rp-profile-type.is-link:focus-visible{ outline:2px solid #FF2D2D; outline-offset:2px; border-radius:4px; }

/* ── Complete-your-profile box (under the action buttons): no border, same fill as the action buttons ── */
.rp-complete{ position:relative; margin:0 var(--rp-header-pad-x) 10px; padding:12px 14px; border-radius:var(--rp-action-radius); background:rgba(255,255,255,0.07); border:none; }
.rp-complete[hidden]{ display:none; }
.rp-complete-t, .rp-complete-s{ padding-right:24px; }   /* room for the ✕ on the text rows only, so the buttons get equal space left and right */
.rp-complete-t{ font-size:clamp(.72rem, .6rem + .6vw, .85rem); font-weight:700; color:#fff; }
.rp-complete-s{ font-size:clamp(.6rem, .5rem + .5vw, .7rem); color:rgba(255,255,255,.5); margin:3px 0 10px; line-height:1.4; }
.rp-complete-btns{ display:flex; gap:clamp(5px, 1.5vw, 8px); }
.rp-complete-btns .rp-rect-btn{ background:rgba(255,255,255,0.1); cursor:pointer; font-family:inherit; }
.rp-complete-btns .rp-rect-btn:hover{ background:rgba(255,255,255,0.18); }
.rp-complete-x{ position:absolute; top:8px; right:8px; width:26px; height:26px; border:none; background:none; color:rgba(255,255,255,.55); font-size:17px; display:flex; align-items:center; justify-content:center; border-radius:50%; cursor:pointer; -webkit-tap-highlight-color:transparent; }
.rp-complete-x:hover{ color:#fff; background:rgba(255,255,255,.08); }

/* ── search icon in the sort bar + the drop-down search (own profile; Memes / Reposts / Tags / Saved) ── */
.g-pill.g-search-btn{ margin-left:auto; position:sticky; right:0; z-index:2; padding:0; width:var(--tab-btn-h); background:linear-gradient(var(--tab-btn-bg),var(--tab-btn-bg)),#06071A; }
.g-pill.g-search-btn i{ font-size:17px; line-height:1; display:block; }
.g-pill.g-search-btn.active{ background:var(--tab-btn-bg-hover); }
.grid-search-wrap{ display:grid; grid-template-rows:0fr; transition:grid-template-rows .26s ease; }
.grid-search-wrap.open{ grid-template-rows:1fr; }
.grid-search-inner{ position:relative; overflow:hidden; min-height:0; margin:0 var(--rp-header-pad-x); }
.grid-search-wrap.open .grid-search-inner{ padding:0 0 10px; }
.grid-search-field{ position:relative; }
.grid-search-inner .msg-search-input{ display:block; padding-right:36px; }
.grid-search-clear{ position:absolute; right:6px; top:50%; transform:translateY(-50%); width:24px; height:24px; border:none; border-radius:50%; background:none; color:rgba(255,255,255,.45); font-size:16px; display:none; align-items:center; justify-content:center; cursor:pointer; padding:0; line-height:1; -webkit-tap-highlight-color:transparent; }
.grid-search-clear:hover{ color:#fff; background:rgba(255,255,255,.1); }
.grid-search-clear.show{ display:flex; }
.grid-search-recent{ display:none; flex-wrap:wrap; gap:6px; padding-top:8px; }
.grid-search-recent.show{ display:flex; }
.grid-search-chip{ display:inline-flex; align-items:center; gap:5px; max-width:100%; height:24px; padding:0 10px; border:none; border-radius:4px; background:rgba(255,255,255,.075); color:rgba(255,255,255,.75); font-size:11px; font-family:Poppins,sans-serif; cursor:pointer; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.grid-search-chip:hover{ background:rgba(255,255,255,.15); color:#fff; }
.grid-search-chip i{ font-size:12px; opacity:.6; }
.grid-search-none{ display:none; text-align:center; padding:26px 16px; font-size:12px; color:rgba(255,255,255,.4); }
.grid-search-none.show{ display:block; }
.grid .meme-card.dz-sr-hide{ display:none !important; }
.grid.dz-paged > .meme-card.dz-hold.dz-sr-show{ display:block; }
.grid.dz-searching .dz-sentinel, .grid.dz-searching .dz-skel-card{ display:none !important; }

/* ── Memes tab: ⌄ chevron beside the word (opens the All / Videos / Text sheet) ── */
/* ══════════ GUIDE (Memes tab → ⌄ → Guide) — minimal: no boxes, hairlines, red for what matters ══════════ */
#dzInfoPanel{ display:none; }
#memes.dz-info-on > *{ display:none !important; }
#memes.dz-info-on > #dzInfoPanel{ display:flex !important; }
/* the Newest / Oldest / Collections bar and the search button sit in the shared dock — hide the Memes ones while the Guide is open */
body.dz-guide-on #memesSortBar{ display:none !important; }
.dzi-wrap{ flex-direction:column; padding:clamp(14px,4vw,22px) var(--rp-header-pad-x) 36px; }
.dzi-wrap .r{ color:#FF2D2D; font-weight:400; }
.dzi-hero{ padding:0 0 clamp(16px,4.5vw,24px); }
.dzi-hero-t{ font-size:clamp(1.15rem, 1rem + 1vw, 1.5rem); font-weight:300; letter-spacing:.01em; color:#fff; line-height:1.1; }
.dzi-hero-t::after{ content:''; display:block; width:22px; height:2px; background:#FF2D2D; margin-top:8px; border-radius:2px; }
.dzi-hero-s{ font-size:clamp(.6rem, .5rem + .5vw, .72rem); line-height:1.6; color:rgba(255,255,255,0.55); margin-top:10px; font-weight:400; }
.dzi-group{ display:flex; flex-direction:column; margin-bottom:clamp(18px,5vw,26px); }
.dzi-glabel{ font-size:clamp(.5rem, .42rem + .4vw, .62rem); font-weight:400; letter-spacing:.16em; text-transform:uppercase; color:#FF2D2D; padding-bottom:8px; border-bottom:1px solid rgba(255,255,255,0.14); }
.dzi-gsub{ font-size:clamp(.58rem, .5rem + .45vw, .7rem); line-height:1.6; color:rgba(255,255,255,0.55); padding-top:9px; font-weight:400; }
.dzi-gact{ margin-top:8px; padding-bottom:2px; }
.dzi-list{ display:flex; flex-direction:column; }
.dzi-item{ padding:clamp(11px,3vw,16px) 0 clamp(12px,3.2vw,17px); border-bottom:1px solid rgba(255,255,255,0.08); }
.dzi-item:last-child{ border-bottom:none; }
.dzi-head{ display:flex; align-items:baseline; gap:10px; }
.dzi-t{ flex:1; min-width:0; font-size:clamp(.7rem, .6rem + .5vw, .86rem); font-weight:500; color:#fff; letter-spacing:.005em; }
.dzi-chip{ flex-shrink:0; max-width:55%; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:clamp(.5rem, .42rem + .4vw, .62rem); font-weight:400; color:rgba(255,255,255,0.38); }
.dzi-chip::before{ content:''; display:inline-block; width:4px; height:4px; border-radius:50%; background:rgba(255,255,255,0.3); margin-right:5px; vertical-align:1px; }
.dzi-chip.on{ color:rgba(255,255,255,0.75); }
.dzi-chip.on::before{ background:#FF2D2D; }
.dzi-demo{ display:flex; flex-wrap:wrap; align-items:center; gap:5px; margin-top:10px; }
.dzi-pill{ display:inline-flex; align-items:center; justify-content:center; height:clamp(19px,5.2vw,23px); padding:0 clamp(9px,2.6vw,12px); border-radius:4px; background:rgba(255,255,255,0.09); color:#fff; font-size:clamp(.5rem, .42rem + .4vw, .62rem); font-weight:500; line-height:1; }
.dzi-link{ font-size:clamp(.56rem, .48rem + .4vw, .68rem); color:rgba(255,255,255,0.85); display:inline-flex; align-items:center; gap:5px; }
.dzi-link i{ font-size:13px; }
.dzi-grey{ font-size:clamp(.56rem, .48rem + .4vw, .68rem); color:rgba(255,255,255,0.45); }
.dzi-dot{ width:9px; height:9px; border-radius:50%; background:#3ccf7a; box-shadow:0 0 0 3px #05061a; display:inline-block; margin-right:6px; }
.dzi-b{ margin:9px 0 0; font-size:clamp(.58rem, .5rem + .45vw, .7rem); line-height:1.65; color:rgba(255,255,255,0.58); font-weight:400; }
.dzi-act{ margin-top:10px; display:flex; flex-wrap:wrap; align-items:center; gap:16px; }
.dzi-btn{ display:inline-flex; align-items:center; gap:5px; padding:2px 0; border:none; background:none; color:#FF2D2D; font-size:clamp(.58rem, .5rem + .45vw, .68rem); font-weight:400; text-decoration:none; cursor:pointer; line-height:1.2; letter-spacing:.01em; -webkit-tap-highlight-color:transparent; }
.dzi-btn::after{ content:'→'; transition:transform .2s ease; }
.dzi-btn:hover::after{ transform:translateX(3px); }
.dzi-plus{ display:inline-flex; align-items:center; justify-content:center; width:14px; height:14px; border-radius:50%; background:#FF2D2D; vertical-align:-3px; margin:0 1px; }
.dzi-plus i{ font-size:10px; color:#05061a; line-height:1; }
/* while the Guide is open the sheet only offers the view switch */
#mfSheet.mf-info .dzm-header:not(.mf-keep), #mfSheet.mf-info .dzm-item:not(.mf-view){ display:none; }
.rp-tab-chev{ display:none; align-items:center; justify-content:center; width:1.15em; height:1.15em; margin-left:-3px; border-radius:50%; color:#fff; font-size:clamp(.62rem, .4rem + .6vw, .78rem); line-height:1; cursor:pointer; position:relative; -webkit-tap-highlight-color:transparent; }
.rp-tab-chev i{ font-size:1.29em; line-height:1; display:block; transform:translateY(1.5px); }
.rp-tab-btn.active .rp-tab-chev{ display:inline-flex; }
.rp-tab-chev:hover{ background:rgba(255,255,255,.1); }
.rp-tab-chev.has-filter{ color:#FF2D2D; }
.rp-tab-chev.has-filter::after{ content:''; position:absolute; top:1px; right:0; width:5px; height:5px; border-radius:50%; background:#FF2D2D; }
