}
.pkbm-back-btn:hover { color: var(--pk-red); opacity: 1; }
.pkbm-back-btn svg { width: 22px; height: 22px; display: block; }
.pkbm-back-btn > i { display: none; }            /* old arrow icon is replaced by the X */
.pkbm-topbar-title {
