            <!-- tap zones -->
            <div class="hl-zone hl-zone-prev" onclick="hlPrev()"></div>
            <div class="hl-zone hl-zone-next" onclick="hlNext()"></div>

            <!-- text written on the media (or a text-only highlight on Text.jpg) -->
