<!-- ══════════════════════════════════════
     SAVE TO COLLECTION (#svshOverlay) — opened by the + circle on a card and by
     "Add to collection" in Post options. Two screens that slide: list ⇄ create.
══════════════════════════════════════ -->
<div id="svshOverlay" onclick="if(event.target===this)svshClose()">
  <div id="svshPanel" class="svsh-panel" role="dialog" aria-modal="true" aria-label="Add to a collection">
    <div class="svsh-screens">

        <!-- SCREEN 1: main sheet -->
        <div class="svsh-screen">
            <div class="svsh-handle"></div>
            <div class="svsh-section-label">Add to a collection</div>

            <div class="svsh-row svsh-create-row" onclick="svshShowCreate()">
                <i class="ri-folder-add-line svsh-row-icon"></i>
                <div class="svsh-row-text">
                    <div class="svsh-row-title">Create a new collection</div>
                    <div class="svsh-row-sub">Save posts to a new collection</div>
                </div>
                <i class="ri-arrow-right-s-line svsh-chevron"></i>
            </div>

            <div class="svsh-collections-list" id="svshList"><div class="svsh-loading">Loading…</div></div>
        </div>

        <!-- SCREEN 2: create collection -->
        <div class="svsh-screen">
            <div class="svsh-create-topbar">
                <button type="button" class="svsh-back-btn" onclick="svshShowList()" aria-label="Back"><i class="ri-arrow-left-s-line"></i></button>
                <div class="svsh-create-title">Create a collection</div>
                <button type="button" class="svsh-done-btn" id="svshDone" onclick="svshCreate()">Done</button>
            </div>
            <div class="svsh-create-body">
                <input type="text" id="svshName" class="svsh-name-input" placeholder="Collection name" maxlength="60" autocomplete="off">
                <div class="svsh-required-hint" id="svshHint">Required</div>

                <div class="svsh-toggle-row">
                    <div class="svsh-toggle-text">
                        <div class="svsh-toggle-title">Set the collection to public</div>
                        <div class="svsh-toggle-sub">Anyone can view this collection</div>
                    </div>
                    <label class="svsh-switch">
                        <input type="checkbox" id="svshPublic">
                        <span class="svsh-switch-slider"></span>
                    </label>
                </div>
            </div>
        </div>

    </div>
  </div>
</div>
<script>
(function(){
    var PID = <?= (int)$profile_id ?>, memeId = 0, inCols = {}, busy = false, evCb = null;
    function emit(ev){ if(typeof evCb === 'function'){ try{ evCb(ev); }catch(e){} } }
    function $(id){ return document.getElementById(id); }
    function esc(t){ var d = document.createElement('div'); d.textContent = t == null ? '' : String(t); return d.innerHTML; }
    function toast(m){ if(typeof window.picModalToast === 'function') window.picModalToast(m); }
    function post(params, cb){
        var body = new URLSearchParams(params);
        fetch(window.location.pathname + '?user_id=' + PID, { method:'POST', credentials:'same-origin', headers:{ 'X-Requested-With':'XMLHttpRequest' }, body: body })
            .then(function(r){ return r.json(); }).then(cb).catch(function(){ cb(null); });
    }

    /* ── pin / unpin (used by the card's pin button and the Post options sheet) ── */
    window.gTogglePin = function(id, btn){
        id = parseInt(id, 10); if(!id || !btn || btn.dataset.busy) return;
        var on = btn.classList.contains('pinned');
        btn.dataset.busy = '1';
        post({ col_action: on ? 'unpin_post' : 'pin_post', meme_id: id }, function(d){
            delete btn.dataset.busy;
            if(d && d.status === 'ok'){
                var now = !!d.pinned;
                btn.classList.toggle('pinned', now);
                btn.setAttribute('aria-pressed', now ? 'true' : 'false');
                var ic = btn.querySelector('i'); if(ic) ic.className = now ? 'ri-pushpin-fill' : 'ri-pushpin-line';
                toast(now ? 'Pinned to your profile' : 'Unpinned');
            } else {
                toast((d && d.message) ? d.message : 'Could not change the pin — try again');
            }
        });
    };

    /* ── Save to collection ── */
    function lock(on){ document.body.style.overflow = on ? 'hidden' : ''; }
    function render(cols){
        var box = $('svshList');
        if(!cols.length){ box.innerHTML = ''; return; }
        box.innerHTML = cols.map(function(c){
            var added = !!inCols[c.id], pub = parseInt(c.is_public, 10) === 1;
            var thumb = !c.thumb
                ? '<div class="svsh-col-thumb svsh-col-thumb-empty"><i class="ri-folder-3-line"></i></div>'
                : (c.thumb_type === 'video'
                    ? '<video class="svsh-col-thumb" src="' + esc(c.thumb) + '#t=0.1" muted playsinline preload="metadata"></video>'
                    : '<img src="' + esc(c.thumb) + '" class="svsh-col-thumb" alt="" onerror="this.onerror=null;this.src=\'uploads/Text.jpg\'">');
            return '<div class="svsh-row svsh-col-row" data-id="' + c.id + '" onclick="svshToggle(' + c.id + ')">'
                 + thumb
                 + '<div class="svsh-row-text"><div class="svsh-row-title">' + esc(c.name) + '</div>'
                 + '<div class="svsh-row-sub"><i class="' + (pub ? 'ri-earth-line' : 'ri-lock-line') + '"></i> ' + (pub ? 'Public' : 'Only me') + '</div></div>'
                 + '<div class="svsh-add-btn' + (added ? ' svsh-added' : '') + '"><i class="' + (added ? 'ri-check-line' : 'ri-add-line') + '"></i></div></div>';
        }).join('');
    }
    var cache = [];
    function refreshCovers(){   /* the cover is the last post added — fetch the fresh list after every change */
        post({ col_action: 'get_collections' }, function(a){ if(a && a.collections){ cache = a.collections; render(cache); } });
    }
    function load(){
        $('svshList').innerHTML = '<div class="svsh-loading">Loading…</div>';
        post({ col_action: 'get_collections' }, function(a){
            post({ col_action: 'meme_in_cols', meme_id: memeId }, function(b){
                cache = (a && a.collections) ? a.collections : [];
                inCols = {}; ((b && b.ids) || []).forEach(function(i){ inCols[i] = 1; });
                if(!a) $('svshList').innerHTML = '<div class="svsh-loading">Could not load — try again</div>'; else render(cache);
            });
        });
    }
    window.openSaveModal = function(id, cb){   /* dzSaveOpen(id) (in the collections script below) calls this with a callback */
        memeId = parseInt(id, 10) || 0; if(!memeId) return;
        evCb = (typeof cb === 'function') ? cb : null;
        $('svshPanel').classList.remove('svsh-create-mode');
        $('svshOverlay').classList.add('open'); lock(true);
        load();
    };
    window.svshClose = function(){ $('svshOverlay').classList.remove('open'); lock(false); };
    window.svshShowCreate = function(){ $('svshPanel').classList.add('svsh-create-mode'); $('svshName').value = ''; $('svshPublic').checked = false; $('svshHint').classList.remove('svsh-error'); setTimeout(function(){ $('svshName').focus(); }, 280); };
    window.svshShowList = function(){ $('svshPanel').classList.remove('svsh-create-mode'); };
    window.svshToggle = function(cid){
        if(busy) return; busy = true;
        var had = !!inCols[cid];
        post({ col_action: had ? 'remove_from_collection' : 'add_to_collection', col_id: cid, meme_id: memeId }, function(d){
            busy = false;
            if(d && (d.status === 'ok' || d.status === 'already')){
                if(had) delete inCols[cid]; else inCols[cid] = 1;
                if(d.item_count != null) cache.forEach(function(c){ if(c.id == cid) c.item_count = d.item_count; });
                render(cache);
                emit({ type:'collection', colId:cid, memeId:memeId, inCollection:!had, itemCount:d.item_count });
                toast(had ? 'Removed from collection' : 'Added to collection');
                refreshCovers();
            } else toast((d && d.message) ? d.message : 'Could not save — try again');
        });
    };
    window.svshCreate = function(){
        var name = $('svshName').value.trim();
        if(!name){ $('svshHint').classList.add('svsh-error'); $('svshName').focus(); return; }
        var btn = $('svshDone'); btn.disabled = true;
        post({ col_action: 'create_collection', name: name, is_public: $('svshPublic').checked ? 1 : 0 }, function(d){
            if(!d || d.status !== 'ok'){ btn.disabled = false; toast((d && d.message) ? d.message : 'Could not create — try again'); return; }
            post({ col_action: 'add_to_collection', col_id: d.id, meme_id: memeId }, function(){
                btn.disabled = false;
                cache = d.collections || cache; inCols[d.id] = 1;
                cache.forEach(function(c){ if(c.id == d.id) c.item_count = Math.max(1, parseInt(c.item_count, 10) || 0); });
                render(cache); svshShowList(); emit({ type:'created', colId:d.id, name:name, isPublic:$('svshPublic').checked, inCollection:true }); toast('Saved to ' + name); refreshCovers();
            });
        });
    };
    $('svshName').addEventListener('input', function(){ $('svshHint').classList.remove('svsh-error'); });
    $('svshName').addEventListener('keydown', function(e){ if(e.key === 'Enter'){ e.preventDefault(); svshCreate(); } });
    document.addEventListener('keydown', function(e){ if(e.key === 'Escape' && $('svshOverlay').classList.contains('open')) svshClose(); });
})();
</script>
<?php endif; ?>

